// Deterministic generator for the UI-005 sync fixtures.
// Emits fixtures/sync_concert.musicxml + fixtures/sync_horn_in_f.musicxml
// following the ENG-001 ID rules (python/hornscribe/domain/ids.py):
//   canonical note -> hs-sn-<6 digits>          (tie fragment k>1 -> hs-sn-<6 digits>-k)
//   rest           -> hs-rest-<6 digits>         (presentation-only)
//
// 12 bars, 4/4, 100 BPM, divisions=480 (1 ql = 480 ticks).
// Known onsets: every canonical note's onset in ql is derivable from the
// note table below — vitest asserts the parsed SyncMap against them.
// Horn fixture is the same canonical content in written pitch (concert +P5,
// key sig 0 -> 1 fifth, transpose diatonic -4 / chromatic -7), so the pair
// exercises the Concert<->F管ホルン switch with identical hs-sn-* ids.
//
// Run: npm run gen:fixtures  (output is committed; regenerate only to change content)

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, '..', 'fixtures');

const DIVISIONS = 480; // ticks per quarter note
const BPM = 100;
const E = DIVISIONS / 2;   // eighth
const Q = DIVISIONS;       // quarter
const DQ = DIVISIONS * 1.5; // dotted quarter
const H = DIVISIONS * 2;   // half

// ---- note table (concert pitch) ------------------------------------------
// type: whole/half/quarter/eighth; dots: n; tie: 'start'|'stop'|'stopstart';
// accidental: MusicXML accidental name when an explicit sign is needed.
// `rest: true` for rests (no canonical id).
const MEASURES = [
  // m1  ql 0–4
  [
    { step: 'C', octave: 4, dur: Q, type: 'quarter' },
    { step: 'E', octave: 4, dur: E, type: 'eighth' },
    { step: 'G', octave: 4, dur: E, type: 'eighth' },
    { step: 'C', octave: 5, dur: Q, type: 'quarter' },
    { step: 'G', octave: 4, dur: Q, type: 'quarter' },
  ],
  // m2  ql 4–8
  [
    { step: 'A', octave: 4, dur: Q, type: 'quarter' },
    { step: 'F', octave: 4, dur: E, type: 'eighth' },
    { step: 'G', octave: 4, dur: E, type: 'eighth' },
    { step: 'E', octave: 4, dur: H, type: 'half' },
  ],
  // m3  ql 8–12  — Bb3 tied across the barline (2 fragments)
  [
    { step: 'D', octave: 4, dur: Q, type: 'quarter' },
    { step: 'F', alter: 1, octave: 4, dur: Q, type: 'quarter', accidental: 'sharp' },
    { step: 'B', alter: -1, octave: 3, dur: DQ, type: 'quarter', dots: 1, tie: 'start', accidental: 'flat' },
    { step: 'A', octave: 3, dur: E, type: 'eighth' },
  ],
  // m4  ql 12–16
  [
    { step: 'B', alter: -1, octave: 3, dur: H, type: 'half', tie: 'stop', continueTie: true },
    { rest: true, dur: H, type: 'half' },
  ],
  // m5  ql 16–20
  [
    { step: 'C', octave: 4, dur: E, type: 'eighth' },
    { step: 'D', octave: 4, dur: E, type: 'eighth' },
    { step: 'E', octave: 4, dur: E, type: 'eighth' },
    { step: 'F', octave: 4, dur: E, type: 'eighth' },
    { step: 'G', octave: 4, dur: Q, type: 'quarter' },
    { step: 'A', octave: 4, dur: Q, type: 'quarter' },
  ],
  // m6  ql 20–24
  [
    { step: 'B', alter: -1, octave: 4, dur: DQ, type: 'quarter', dots: 1, accidental: 'flat' },
    { step: 'A', octave: 4, dur: E, type: 'eighth' },
    { step: 'G', octave: 4, dur: H, type: 'half' },
  ],
  // m7  ql 24–28 — D4 tied into m8 (2 fragments)
  [
    { step: 'F', octave: 4, dur: Q, type: 'quarter' },
    { step: 'E', octave: 4, dur: Q, type: 'quarter' },
    { step: 'D', octave: 4, dur: H, type: 'half', tie: 'start' },
  ],
  // m8  ql 28–32
  [
    { step: 'D', octave: 4, dur: E, type: 'eighth', tie: 'stop', continueTie: true },
    { step: 'E', octave: 4, dur: E, type: 'eighth' },
    { step: 'F', octave: 4, dur: H, type: 'half' },
    { rest: true, dur: Q, type: 'quarter' },
  ],
  // m9  ql 32–36
  [
    { step: 'G', octave: 4, dur: Q, type: 'quarter' },
    { step: 'A', octave: 4, dur: Q, type: 'quarter' },
    { step: 'B', octave: 4, dur: Q, type: 'quarter' },
    { step: 'C', octave: 5, dur: Q, type: 'quarter' },
  ],
  // m10  ql 36–40
  [
    { step: 'D', octave: 5, dur: H, type: 'half' },
    { step: 'C', octave: 5, dur: E, type: 'eighth' },
    { step: 'B', octave: 4, dur: E, type: 'eighth' },
    { step: 'G', octave: 4, dur: Q, type: 'quarter' },
  ],
  // m11  ql 40–44 — G4 tied into m12 (3 fragments total)
  [
    { step: 'A', octave: 4, dur: Q, type: 'quarter' },
    { step: 'F', octave: 4, dur: Q, type: 'quarter' },
    { step: 'G', octave: 4, dur: H, type: 'half', tie: 'start' },
  ],
  // m12  ql 44–48
  [
    { step: 'G', octave: 4, dur: Q, type: 'quarter', tie: 'stopstart', continueTie: true },
    { step: 'G', octave: 4, dur: E, type: 'eighth', tie: 'stop', continueTie: true },
    { step: 'F', octave: 4, dur: E, type: 'eighth' },
    { step: 'E', octave: 4, dur: H, type: 'half' },
  ],
];

// Horn in F: written pitch = concert + perfect 5th (+7 semitones, +4 diatonic).
const STEP_INDEX = { C: 0, D: 1, E: 2, F: 3, G: 4, A: 5, B: 6 };
const STEP_SEMITONE = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
const INDEX_STEP = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];

function toHornPitch(step, alter = 0, octave) {
  // Transpose sounding midi up a perfect 5th, then re-spell +4 diatonic steps
  // (the F-horn convention: written pitch sits a P5 above sounding pitch).
  const midi = (octave + 1) * 12 + STEP_SEMITONE[step] + alter + 7;
  const newOctave = Math.floor(midi / 12) - 1;
  const pc = midi % 12;
  const newStep = INDEX_STEP[(STEP_INDEX[step] + 4) % 7];
  const newAlter = pc - STEP_SEMITONE[newStep];
  return { step: newStep, alter: newAlter, octave: newOctave };
}

// Accidental name for the *written* pitch given the horn key sig (G major:
// F is sharp by default). Emit only when the written alter deviates from
// the key signature — e.g. concert Bb -> written F natural needs 'natural',
// concert F# -> written C# needs 'sharp' (same convention as golden_v1_horn).
function hornAccidental(step, alter) {
  const implicit = step === 'F' ? 1 : 0; // fifths = 1
  if (alter === implicit) return null;
  if (alter === 1) return 'sharp';
  if (alter === -1) return 'flat';
  return 'natural';
}

let noteSeq = 0;
let restSeq = 0;
let openTieSeq = null; // canonical seq of the note with an open tie
let openTieFrag = 0;   // last fragment ordinal emitted for it

function noteXml(n, id, pitch /* {step, alter, octave} */, accidental) {
  const lines = [];
  lines.push(`      <note id="${id}">`);
  if (n.rest) {
    lines.push('        <rest />');
  } else {
    lines.push('        <pitch>');
    lines.push(`          <step>${pitch.step}</step>`);
    // Emit <alter> when non-zero, and explicitly as 0 when an accidental
    // documents a deviation from the key (golden fixture convention).
    if (pitch.alter || accidental) lines.push(`          <alter>${pitch.alter}</alter>`);
    lines.push(`          <octave>${pitch.octave}</octave>`);
    lines.push('        </pitch>');
  }
  lines.push(`        <duration>${n.dur}</duration>`);
  if (n.tie === 'stop' || n.tie === 'stopstart') lines.push('        <tie type="stop" />');
  if (n.tie === 'start' || n.tie === 'stopstart') lines.push('        <tie type="start" />');
  lines.push(`        <type>${n.type}</type>`);
  for (let i = 0; i < (n.dots ?? 0); i++) lines.push('        <dot />');
  if (accidental) lines.push(`        <accidental>${accidental}</accidental>`);
  if (n.tie) {
    lines.push('        <notations>');
    if (n.tie === 'stop' || n.tie === 'stopstart') lines.push('          <tied type="stop" />');
    if (n.tie === 'start' || n.tie === 'stopstart') lines.push('          <tied type="start" />');
    lines.push('        </notations>');
  }
  lines.push('      </note>');
  return lines.join('\n');
}

function emit(xmlNoteTable, { horn }) {
  noteSeq = 0;
  restSeq = 0;

  const measuresOut = [];
  xmlNoteTable.forEach((notes, mi) => {
    const body = [];
    if (mi === 0) {
      body.push(`      <attributes>
        <divisions>${DIVISIONS}</divisions>
        <key>
          <fifths>${horn ? 1 : 0}</fifths>
        </key>
        <time>
          <beats>4</beats>
          <beat-type>4</beat-type>
        </time>
        <clef>
          <sign>G</sign>
          <line>2</line>
        </clef>${horn ? `
        <transpose>
          <diatonic>-4</diatonic>
          <chromatic>-7</chromatic>
        </transpose>` : ''}
      </attributes>`);
      body.push(`      <direction>
        <direction-type>
          <metronome parentheses="no">
            <beat-unit>quarter</beat-unit>
            <per-minute>${BPM}</per-minute>
          </metronome>
        </direction-type>
        <sound tempo="${BPM}" />
      </direction>`);
    }
    for (const n of notes) {
      let id;
      if (n.rest) {
        id = `hs-rest-${String(++restSeq).padStart(6, '0')}`;
      } else if (n.continueTie) {
        // Tie fragment k>=2 of the note that opened the tie. Fragments are
        // consecutive <note> elements of the same canonical note, but other
        // canonical notes (e.g. the A3 eighth in m.3) may intervene, so the
        // open tie is tracked separately from "previous note".
        if (openTieSeq === null) {
          throw new Error(`continueTie with no open tie (measure ${mi + 1})`);
        }
        openTieFrag += 1;
        id = `hs-sn-${String(openTieSeq).padStart(6, '0')}-${openTieFrag}`;
        if (n.tie === 'stop') openTieSeq = null; // 'stopstart' keeps it open
      } else {
        id = `hs-sn-${String(++noteSeq).padStart(6, '0')}`;
        if (n.tie === 'start' || n.tie === 'stopstart') {
          openTieSeq = noteSeq;
          openTieFrag = 1;
        }
      }
      const pitch = n.rest
        ? null
        : horn
          ? toHornPitch(n.step, n.alter ?? 0, n.octave)
          : { step: n.step, alter: n.alter ?? 0, octave: n.octave };
      const accidental = n.rest
        ? null
        : horn
          ? hornAccidental(pitch.step, pitch.alter)
          : n.accidental ?? null;
      body.push(noteXml(n, id, pitch, accidental));
    }
    measuresOut.push(`    <measure implicit="no" number="${mi + 1}">\n${body.join('\n')}\n    </measure>`);
  });

  return `<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE score-partwise PUBLIC "-//Recordare//DTD MusicXML 4.0 Partwise//EN" "http://www.musicxml.org/dtds/partwise.dtd">
<score-partwise version="4.0">
  <work>
    <work-title>Sync Fixture${horn ? ' (Horn in F)' : ''}</work-title>
  </work>
  <movement-title>UI-005 Sync Fixture${horn ? ' — F管ホルン' : ''}</movement-title>
  <identification>
    <creator type="composer">HornScribe spike generator</creator>
    <encoding>
      <software>apps/spikes/score-audio-sync/scripts/gen-fixtures.mjs</software>
      <supports element="beam" type="yes" />
      <supports element="stem" type="yes" />
      <supports element="accidental" type="yes" />
    </encoding>
  </identification>
  <defaults>
    <scaling>
      <millimeters>7</millimeters>
      <tenths>40</tenths>
    </scaling>
  </defaults>
  <part-list>
    <score-part id="P1">
      <part-name>Horn in F</part-name>${horn ? `
      <score-instrument id="I1">
        <instrument-name>Horn in F</instrument-name>
      </score-instrument>
      <midi-instrument id="I1">
        <midi-channel>1</midi-channel>
        <midi-program>61</midi-program>
      </midi-instrument>` : ''}
    </score-part>
  </part-list>
  <part id="P1">
${measuresOut.join('\n')}
  </part>
</score-partwise>
`;
}

const concert = emit(MEASURES, { horn: false });
const horn = emit(MEASURES, { horn: true });
writeFileSync(join(outDir, 'sync_concert.musicxml'), concert, 'utf8');
writeFileSync(join(outDir, 'sync_horn_in_f.musicxml'), horn, 'utf8');
console.log(`wrote sync_concert.musicxml + sync_horn_in_f.musicxml (${noteSeq} canonical notes, ${restSeq} rests, ${MEASURES.length} measures, ${BPM} BPM)`);

/**
 * UI-005 measurement driver.
 *
 * Serves the production build (vite preview) and drives the in-page harness
 * (src/measure/harness.ts, exposed as window.__ui005) with a real
 * Chromium-family browser via puppeteer-core — Chrome by default (same
 * Blink/V8 family as the WebView2 target; Edge headless conflicts with
 * existing Edge sessions on some machines — see UI-004 results).
 *
 *   node scripts/measure.mjs [--browser=edge|chrome] [--url=http://localhost:4173]
 *                            [--fixture=steady|warped] [--port=4173]
 *
 * Writes measurements/ui-005-<timestamp>.json and prints the same JSON.
 */
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { spawn } from 'node:child_process'
import puppeteer from 'puppeteer-core'

const here = dirname(fileURLToPath(import.meta.url))
const appDir = join(here, '..')
const outDir = join(appDir, 'measurements')

const args = process.argv.slice(2)
const browserArg = args.find((a) => a.startsWith('--browser='))?.split('=')[1] ?? 'chrome'
const explicitUrl = args.find((a) => a.startsWith('--url='))?.split('=')[1]
const fixtures = args.find((a) => a.startsWith('--fixture='))?.split('=')[1]?.split(',') ?? [
  'steady',
  'warped',
]
const port = args.find((a) => a.startsWith('--port='))?.split('=')[1] ?? '4173'

const BROWSERS = {
  edge: [
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
  ],
  chrome: [
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
  ],
}

function findBrowser() {
  const candidates = [...(BROWSERS[browserArg] ?? []), ...BROWSERS.chrome, ...BROWSERS.edge]
  for (const p of candidates) if (existsSync(p)) return p
  throw new Error('No Edge/Chrome executable found for puppeteer-core')
}

async function waitForServer(url, tries = 60) {
  for (let i = 0; i < tries; i += 1) {
    try {
      const r = await fetch(url)
      if (r.ok) return
    } catch {
      /* not up yet */
    }
    await new Promise((r) => setTimeout(r, 500))
  }
  throw new Error(`server did not start: ${url}`)
}

async function main() {
  const browserPath = findBrowser()
  console.log(`browser: ${browserPath}`)

  let server = null
  const baseUrl = explicitUrl ?? `http://localhost:${port}`
  if (!explicitUrl) {
    server = spawn(
      process.execPath,
      [
        join(appDir, 'node_modules/vite/bin/vite.js'),
        'preview',
        '--port',
        port,
        '--strictPort',
      ],
      { cwd: appDir, stdio: 'pipe' },
    )
    server.stderr?.on('data', (d) => process.stderr.write(d))
    await waitForServer(baseUrl)
    console.log(`preview server: ${baseUrl}`)
  }

  const browser = await puppeteer.launch({
    executablePath: browserPath,
    headless: true,
    protocolTimeout: 600_000,
    args: [
      '--autoplay-policy=no-user-gesture-required',
      '--mute-audio',
      '--disable-renderer-backgrounding',
      '--window-size=1600,900',
      '--no-sandbox',
      `--user-data-dir=${process.env.TEMP ?? '.'}/ui005-measure-profile`,
    ],
  })

  const reports = []
  try {
    const page = await browser.newPage()
    await page.setViewport({ width: 1600, height: 900 })
    page.on('pageerror', (e) => console.error('pageerror:', e.message))
    page.on('console', (m) => {
      if (m.type() === 'error') console.error('console.error:', m.text())
    })

    await page.goto(baseUrl, { waitUntil: 'networkidle0' })
    await page.waitForFunction('window.__ui005 !== undefined', { timeout: 30000 })

    for (const id of fixtures) {
      console.log(`\n=== fixture ${id} ===`)
      await page.evaluate((fid) => window.__ui005.setFixture(fid), id)
      await page.waitForFunction('window.__ui005.ready()', { timeout: 30000 })
      const report = await page.evaluate(() => window.__ui005.runCurrent(), {
        timeout: 300_000,
      })
      report.fixtureId = id
      reports.push(report)
      console.log(
        `  seek p50=${report.scoreClickSeek?.medianMs?.toFixed(1)}ms ` +
          `wave p50=${report.waveClickSelect?.medianMs?.toFixed(1)}ms ` +
          `sync lag mean=${report.sync?.lagMeanMs?.toFixed(1)}ms ` +
          `react=${report.sync?.reactRenders} verovio=${report.sync?.verovioRenderCalls} ` +
          `loop drift=${report.loopDrift?.periodErrMeanMs?.toFixed(1)}ms`,
      )
    }
  } finally {
    await browser.close()
    server?.kill()
  }

  const doc = {
    tool: 'ui-005-spike',
    timestamp: new Date().toISOString(),
    userAgent: reports.length ? undefined : '',
    browser: browserPath,
    fixtures: reports,
  }
  mkdirSync(outDir, { recursive: true })
  const file = join(outDir, `ui-005-${Date.now()}.json`)
  writeFileSync(file, JSON.stringify(doc, null, 2))
  console.log(`\nwrote ${file}`)
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react'
import { encodeWavPcm16Mono } from './audio/wav'
import { synthScoreAudio } from './audio/synth'
import { MeasurePanel } from './components/MeasurePanel'
import { ScoreView } from './components/ScoreView'
import { TransportBar } from './components/TransportBar'
import { WaveformView } from './components/WaveformView'
import { copy, spikeCopy, t } from './copy'
import { FIXTURES, fixtureXml, type FixtureId, type PitchView } from './fixtures'
import { runMeasurements, type SyncHooks, type SyncReport } from './measure/harness'
import {
  ACTIVE_CLASS,
  LOOP_CLASS,
  MEASURE_ACTIVE_CLASS,
  SELECTED_CLASS,
  buildElementIndex,
  markCanonical,
  markCanonicalSet,
  markMeasures,
  type ElementIndex,
} from './score/domScore'
import { canonicalNoteIdFromMusicxml } from './score/ids'
import { describeNote, parseScoreDoc, pitchLabel, type ScoreDoc } from './score/scoreDoc'
import { getScoreRenderer, renderStats, type RenderedPage, type ScoreRenderer } from './score/verovio'
import { ScoreSyncEngine, sameSet } from './sync/syncEngine'
import { buildSyncMap, pitchMidiByCanonical } from './sync/syncMap'
import type { WaveSurferTransportAdapter } from './transport/wavesurferAdapter'
import type { TransportSnapshot } from './transport/types'

const EMPTY_SNAPSHOT: TransportSnapshot = {
  status: 'empty',
  time: 0,
  duration: 0,
  rate: 1,
  preservePitch: true,
  loop: null,
  revision: 0,
}

interface Selection {
  exportId: string
  canonicalId: string | null
  onsetSec: number | null
  measure: number | null
}

/** Spike instrumentation counters (read by the measurement harness). */
let renderCount = 0
const followScrollMs: number[] = []
const highlightMs: number[] = []

const nextFrame = () => new Promise<number>((r) => requestAnimationFrame(r))

export default function App() {
  renderCount += 1
  const adapterRef = useRef<WaveSurferTransportAdapter | null>(null)
  const rendererRef = useRef<ScoreRenderer | null>(null)
  const scoreRef = useRef<HTMLDivElement>(null)
  const indexRef = useRef<ElementIndex | null>(null)
  const engineRef = useRef<ScoreSyncEngine | null>(null)
  const didInit = useRef(false)

  const [fixtureId, setFixtureId] = useState<FixtureId>('steady')
  const [view, setView] = useState<PitchView>('concert')
  const [zoom, setZoom] = useState(100)
  const [pages, setPages] = useState<RenderedPage[]>([])
  const [scoreDoc, setScoreDoc] = useState<ScoreDoc | null>(null)
  const [snapshot, setSnapshot] = useState<TransportSnapshot>(EMPTY_SNAPSHOT)
  const [selection, setSelection] = useState<Selection | null>(null)
  const [activeCanonicals, setActiveCanonicals] = useState<ReadonlySet<string>>(new Set())
  const [currentMeasure, setCurrentMeasure] = useState<number | null>(null)
  const [loopMeasures, setLoopMeasures] = useState<number[]>([])
  const [hasSelection, setHasSelection] = useState(false)
  const [follow, setFollow] = useState(true)
  const [followSuspended, setFollowSuspended] = useState(false)
  const [audioReady, setAudioReady] = useState(false)
  const [scoreReady, setScoreReady] = useState(false)
  const [renderError, setRenderError] = useState(false)
  const [initError, setInitError] = useState<string | null>(null)
  const [version, setVersion] = useState('')
  const [report, setReport] = useState<SyncReport | null>(null)
  const [measuring, setMeasuring] = useState(false)
  const [measureStage, setMeasureStage] = useState('')

  // Refs mirrored so the rAF pump / layout effect always see fresh values.
  const selectionRef = useRef<Selection | null>(null)
  const activeRef = useRef<ReadonlySet<string>>(new Set())
  const loopCanonicalsRef = useRef<ReadonlySet<string>>(new Set())
  const followRef = useRef(true)
  const suspendedRef = useRef(false)
  const zoomRef = useRef(100)
  const fixtureIdRef = useRef(fixtureId)
  const viewRef = useRef(view)
  followRef.current = follow
  suspendedRef.current = followSuspended
  zoomRef.current = zoom
  fixtureIdRef.current = fixtureId
  viewRef.current = view

  const transport = useCallback(() => adapterRef.current, [])

  // ---- DOM-only sync appliers (never re-render) ----------------------------

  const applyActiveDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current
    const container = scoreRef.current
    if (!idx || !container) return
    const t0 = performance.now()
    markCanonicalSet(idx, canonicals, ACTIVE_CLASS)
    const els: Element[] = []
    for (const id of canonicals) els.push(...(idx.byCanonical.get(id) ?? []))
    markMeasures(container, els, MEASURE_ACTIVE_CLASS, true)
    highlightMs.push(performance.now() - t0)
  }, [])

  const applyLoopDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current
    if (!idx) return
    markCanonicalSet(idx, canonicals, LOOP_CLASS)
  }, [])

  const scrollCanonicalIntoView = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current
    if (!idx || canonicals.size === 0) return
    // Earliest-onset active note leads the scroll target (engine order).
    const engine = engineRef.current
    let target: Element | null = null
    if (engine) {
      for (const span of engine.map.spans) {
        if (canonicals.has(span.canonicalId)) {
          target = idx.byCanonical.get(span.canonicalId)?.[0] ?? null
          break
        }
      }
    }
    target ??= idx.byCanonical.get([...canonicals][0])?.[0] ?? null
    if (!target) return
    const t0 = performance.now()
    target.scrollIntoView({ block: 'nearest', inline: 'nearest' })
    followScrollMs.push(performance.now() - t0)
  }, [])

  // ---- score render ---------------------------------------------------------

  const renderScore = useCallback(
    (v: PitchView, z: number, fId: FixtureId) => {
      const r = rendererRef.current
      if (!r) return
      try {
        r.setZoom(z)
        const xml = fixtureXml(fId, v)
        const ok = r.load(xml)
        const doc = ok ? parseScoreDoc(xml) : null
        if (!ok || !doc || doc.notes.length === 0) throw new Error('score load produced no content')
        setPages(r.renderAllPages())
        setScoreDoc(doc)
        setRenderError(false)
      } catch (e) {
        console.error('[UI-005] score render failed:', e)
        setPages([])
        setRenderError(true)
      }
    },
    [],
  )

  // ---- init: renderer + sync map + synthesized audio ------------------------

  const loadAudio = useCallback(async (fId: FixtureId) => {
    const adapter = adapterRef.current
    if (!adapter) return
    const fixture = FIXTURES[fId]
    const warp = fixture.buildWarp()
    // Canonical structure is identical in concert/horn (same ids+durations);
    // the map is built once from the concert document — the canonical side
    // of the chain never depends on which presentation is rendered.
    const map = buildSyncMap(fixture.concertXml)
    const engine = new ScoreSyncEngine(map, warp)
    engineRef.current = engine
    const pitches = pitchMidiByCanonical(fixture.concertXml)
    const notes = [...pitches.values()].map(({ midi, span }) => ({ midi, span }))
    const pcm = synthScoreAudio({
      notes,
      warp,
      tailSec: 0.8,
    })
    const blob = encodeWavPcm16Mono(pcm, 44100)
    setAudioReady(false)
    adapter.clearSelection()
    await adapter.load({ kind: 'blob', blob })
    setAudioReady(true)
  }, [])

  useEffect(() => {
    if (didInit.current) return
    didInit.current = true
    let cancelled = false
    getScoreRenderer()
      .then((r) => {
        if (cancelled) return
        rendererRef.current = r
        setVersion(r.version)
        renderScore(view, zoomRef.current, fixtureId)
        setScoreReady(true)
      })
      .catch((e: unknown) => setInitError(e instanceof Error ? e.message : String(e)))
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Audio loads once the wavesurfer adapter exists (WaveformView mount).
  const onAdapter = useCallback(
    (adapter: WaveSurferTransportAdapter) => {
      adapterRef.current = adapter
      adapter.subscribe(setSnapshot)
      adapter.setSelectionListener((sel) => setHasSelection(sel !== null))
      adapter.setFollow(true)
      void loadAudio(fixtureIdRef.current)
    },
    [loadAudio],
  )

  // ---- per-frame sync pump (DOM-only, no React state on the frame path) ------

  useEffect(() => {
    let raf = 0
    const tick = () => {
      const adapter = adapterRef.current
      const engine = engineRef.current
      const idx = indexRef.current
      if (adapter && engine && idx && adapter.getDuration() > 0) {
        const time = adapter.getCurrentTime()
        const set = engine.activeAtSeconds(time)
        if (!sameSet(set, activeRef.current)) {
          activeRef.current = set
          applyActiveDom(set)
          setActiveCanonicals(set)
          setCurrentMeasure(engine.measureAtSeconds(time)?.number ?? null)
          if (followRef.current && !suspendedRef.current && adapter.core.isPlaying()) {
            scrollCanonicalIntoView(set)
          }
        }
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [applyActiveDom, scrollCanonicalIntoView])

  // After each (re)render of the SVG: rebuild the element index and reapply
  // selection/active/loop marks — also how they survive Concert↔Horn and zoom.
  useLayoutEffect(() => {
    const container = scoreRef.current
    if (!container || pages.length === 0) return
    indexRef.current = buildElementIndex(container)
    const sel = selectionRef.current
    if (sel?.canonicalId) {
      markCanonical(indexRef.current, sel.canonicalId, SELECTED_CLASS)
    } else if (sel) {
      indexRef.current.byExportId.get(sel.exportId)?.classList.add(SELECTED_CLASS)
    }
    markCanonicalSet(indexRef.current, activeRef.current, ACTIVE_CLASS)
    markCanonicalSet(indexRef.current, loopCanonicalsRef.current, LOOP_CLASS)
    // Reapply the measure wash too — it would otherwise be lost until the
    // next active-set change after a view switch / zoom re-render.
    const actEls: Element[] = []
    for (const id of activeRef.current) {
      actEls.push(...(indexRef.current.byCanonical.get(id) ?? []))
    }
    markMeasures(container, actEls, MEASURE_ACTIVE_CLASS, true)
  }, [pages])

  // ---- interactions ---------------------------------------------------------

  /** Score click: export id -> canonical -> onset ql -> seconds -> seek. */
  const selectExportId = useCallback(
    (exportId: string, opts: { seek?: boolean } = {}) => {
      const engine = engineRef.current
      const canonicalId = canonicalNoteIdFromMusicxml(exportId)
      const span = canonicalId ? engine?.span(canonicalId) : null
      const onsetSec = canonicalId ? (engine?.secondsForCanonical(canonicalId) ?? null) : null
      const sel: Selection = {
        exportId,
        canonicalId,
        onsetSec,
        measure: span?.measure ?? null,
      }
      selectionRef.current = sel
      setSelection(sel)
      const idx = indexRef.current
      if (idx) {
        markCanonical(idx, canonicalId, SELECTED_CLASS)
        if (!canonicalId) idx.byExportId.get(exportId)?.classList.add(SELECTED_CLASS)
      }
      if (opts.seek !== false && onsetSec !== null) {
        void adapterRef.current?.seek(onsetSec)
      }
    },
    [],
  )

  /** Waveform click path: audio seconds -> nearest canonical -> select+reveal. */
  const selectAtSeconds = useCallback((timeSec: number) => {
    const engine = engineRef.current
    if (!engine) return
    const span = engine.nearestCanonicalAtSeconds(timeSec)
    if (!span) return
    const sel: Selection = {
      exportId: span.exportIds[0],
      canonicalId: span.canonicalId,
      onsetSec: engine.secondsForCanonical(span.canonicalId),
      measure: span.measure,
    }
    selectionRef.current = sel
    setSelection(sel)
    const idx = indexRef.current
    if (idx) {
      markCanonical(idx, span.canonicalId, SELECTED_CLASS)
      idx.byCanonical.get(span.canonicalId)?.[0]?.scrollIntoView({
        block: 'nearest',
        inline: 'nearest',
      })
    }
    setCurrentMeasure(engine.measureAtSeconds(timeSec)?.number ?? span.measure)
  }, [])

  const onWaveformSeek = useCallback(
    (timeSec: number) => {
      // wavesurfer already performed the audio seek; resolve score context.
      selectAtSeconds(timeSec)
    },
    [selectAtSeconds],
  )

  const suspendFollow = useCallback(() => {
    if (!followRef.current || suspendedRef.current) return
    suspendedRef.current = true
    setFollowSuspended(true)
    adapterRef.current?.setFollow(false)
  }, [])

  const resumeFollow = useCallback(() => {
    suspendedRef.current = false
    setFollowSuspended(false)
    setFollow(true)
    followRef.current = true
    adapterRef.current?.setFollow(true)
    // Re-anchor immediately on the current active note.
    scrollCanonicalIntoView(activeRef.current)
  }, [scrollCanonicalIntoView])

  const onToggleFollow = useCallback(() => {
    if (follow && !followSuspended) {
      // turning follow off entirely
      setFollow(false)
      followRef.current = false
      adapterRef.current?.setFollow(false)
    } else {
      resumeFollow()
    }
  }, [follow, followSuspended, resumeFollow])

  /** Concert↔Horn: reload + re-render; transport/selection untouched.
   *  Compares against viewRef (not the render-time `view` state) so a stale
   *  closure — e.g. the measurement harness holding an older callback — can
   *  never skip a real switch. */
  const switchView = useCallback(
    async (v: PitchView) => {
      if (v === viewRef.current) return
      viewRef.current = v
      setView(v)
      renderScore(v, zoomRef.current, fixtureIdRef.current)
      // marks reapply in the layout effect on the new pages
      await nextFrame()
      await nextFrame()
    },
    [renderScore],
  )

  const changeFixture = useCallback(
    async (fId: FixtureId) => {
      if (fId === fixtureIdRef.current) return
      fixtureIdRef.current = fId
      setFixtureId(fId)
      selectionRef.current = null
      setSelection(null)
      loopCanonicalsRef.current = new Set()
      setLoopMeasures([])
      // MusicXML is shared across fixtures — only the warp+audio change.
      // Rebuild the engine inside loadAudio, then re-render is unnecessary.
      await loadAudio(fId)
    },
    [loadAudio],
  )

  const changeZoom = useCallback(
    (z: number) => {
      zoomRef.current = z
      setZoom(z)
      renderScore(viewRef.current, z, fixtureIdRef.current)
    },
    [renderScore],
  )

  // Loop -> score passage indication, driven by transport snapshots.
  useEffect(() => {
    const loop = snapshot.loop
    const engine = engineRef.current
    if (!engine) return
    const set = loop ? engine.canonicalsInRange(loop) : new Set<string>()
    if (!sameSet(set, loopCanonicalsRef.current)) {
      loopCanonicalsRef.current = set
      applyLoopDom(set)
      setLoopMeasures(loop ? engine.measuresInRange(loop).map((m) => m.number) : [])
    }
  }, [snapshot.loop, applyLoopDom])

  const onToggleLoop = useCallback(() => {
    const adapter = adapterRef.current
    if (!adapter) return
    if (adapter.getSnapshot().loop) adapter.setLoop(null)
    else {
      const sel = adapter.getSelection()
      if (sel) adapter.setLoop(sel)
    }
  }, [])

  const runMeasure = useCallback(async (): Promise<SyncReport | null> => {
    const adapter = adapterRef.current
    const engine = engineRef.current
    if (!adapter || !engine || adapter.getSnapshot().status === 'empty') return null
    setMeasuring(true)
    try {
      const hooks: SyncHooks = {
        adapter,
        engine,
        clickCanonical: async (canonicalId) => {
          const sec = engine.secondsForCanonical(canonicalId)
          if (sec === null) return
          const span = engine.span(canonicalId)
          if (span) selectExportId(span.exportIds[0], { seek: false })
          await adapter.seek(sec)
        },
        selectAtSeconds,
        domActiveCanonicals: () => domCanonicalSet(ACTIVE_CLASS),
        domLoopCanonicals: () => domCanonicalSet(LOOP_CLASS),
        selectedCanonical: () => selectionRef.current?.canonicalId ?? null,
        switchView: (v) => switchView(v),
        getRenderCount: () => renderCount,
        getVerovioRenderCalls: () => renderStats.renderToSVGCalls,
        drainFollowScrollMs: () => followScrollMs.splice(0),
        drainHighlightMs: () => highlightMs.splice(0),
      }
      const r = await runMeasurements({
        hooks,
        fixtureLabel: FIXTURES[fixtureId].labelJa,
        warpMode: engine.warp.mode,
        onProgress: setMeasureStage,
      })
      setReport(r)
      return r
    } finally {
      setMeasuring(false)
      setMeasureStage('')
    }
  }, [fixtureId, selectAtSeconds, selectExportId, switchView])

  function domCanonicalSet(cls: string): Set<string> {
    const out = new Set<string>()
    const container = scoreRef.current
    if (!container) return out
    for (const el of Array.from(container.querySelectorAll(`.${cls}`))) {
      const c = canonicalNoteIdFromMusicxml(el.id)
      if (c) out.add(c)
    }
    return out
  }

  // Puppeteer/measurement bridge.
  useEffect(() => {
    const api = {
      adapter: () => adapterRef.current,
      engine: () => engineRef.current,
      ready: () =>
        adapterRef.current !== null &&
        engineRef.current !== null &&
        adapterRef.current.getSnapshot().status !== 'empty' &&
        pages.length > 0,
      runCurrent: () => runMeasure(),
      switchView,
      selectAtSeconds,
      setFixture: (id: FixtureId) => changeFixture(id),
      getRenderCount: () => renderCount,
      getVerovioRenderCalls: () => renderStats.renderToSVGCalls,
    }
    ;(window as unknown as { __ui005?: unknown }).__ui005 = api
  }, [pages.length, runMeasure, switchView, selectAtSeconds, changeFixture])

  // Keyboard transport (deck tooltips: Space/K/J/L, Home/End, Ctrl+L, Ctrl+1/2).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement
      if (el && (el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA'))
        return
      const c = adapterRef.current
      if (!c || c.getSnapshot().status === 'empty' || c.getSnapshot().status === 'loading') return
      switch (e.code) {
        case 'Space':
          e.preventDefault()
          if (e.shiftKey) c.stop()
          else if (c.getSnapshot().status === 'playing') c.pause()
          else void c.play()
          break
        case 'KeyK':
          if (c.getSnapshot().status === 'playing') c.pause()
          else void c.play()
          break
        case 'KeyJ':
          void c.seek(c.getCurrentTime() - 5)
          break
        case 'KeyL':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault()
            onToggleLoop()
          } else {
            void c.seek(c.getCurrentTime() + 5)
          }
          break
        case 'Home':
          e.preventDefault()
          void c.seek(0)
          break
        case 'End':
          e.preventDefault()
          void c.seek(c.getDuration())
          break
        case 'Digit1':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault()
            void switchView('concert')
          }
          break
        case 'Digit2':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault()
            void switchView('horn')
          }
          break
        case 'Escape':
          selectionRef.current = null
          setSelection(null)
          if (indexRef.current) markCanonical(indexRef.current, null, SELECTED_CLASS)
          adapterRef.current?.clearSelection()
          break
        default:
          break
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onToggleLoop, switchView])

  const ready = audioReady && scoreReady && snapshot.status !== 'empty'
  const selectedNote = selection
    ? (scoreDoc?.notes.find((n) => n.exportId === selection.exportId) ?? null)
    : null

  return (
    <div className="hs-app">
      <header className="hs-header">
        <h1>{spikeCopy.title}</h1>
        <p className="hs-subtitle">{spikeCopy.subtitle}</p>
      </header>

      <div className="hs-toolbar" role="toolbar" aria-label={copy.score.toolbarAria}>
        <label className="hs-field">
          {spikeCopy.fixtureLabel}
          <select
            value={fixtureId}
            onChange={(e) => void changeFixture(e.target.value as FixtureId)}
          >
            <option value="steady">{FIXTURES.steady.labelJa}</option>
            <option value="warped">{FIXTURES.warped.labelJa}</option>
          </select>
        </label>

        <div className="hs-segment" role="group" aria-label={copy.a11y.viewSwitcher}>
          <button
            type="button"
            aria-pressed={view === 'concert'}
            title={copy.seg.concertPitchTooltip}
            onClick={() => void switchView('concert')}
          >
            {copy.seg.concertPitch}
          </button>
          <button
            type="button"
            aria-pressed={view === 'horn'}
            title={copy.seg.hornInFTooltip}
            onClick={() => void switchView('horn')}
          >
            {copy.seg.hornInF}
          </button>
          {view === 'horn' && <span className="hs-horn-caption">{copy.seg.hornCaption}</span>}
        </div>

        <div className="hs-zoom" role="group" aria-label={copy.score.zoomAria}>
          <button
            type="button"
            aria-label={spikeCopy.zoomOut}
            onClick={() => changeZoom(Math.max(25, zoom - 25))}
          >
            −
          </button>
          <input
            type="range"
            min={25}
            max={200}
            step={25}
            value={zoom}
            aria-label={spikeCopy.scoreZoom}
            onChange={(e) => changeZoom(Number(e.target.value))}
          />
          <button
            type="button"
            aria-label={spikeCopy.zoomIn}
            onClick={() => changeZoom(Math.min(200, zoom + 25))}
          >
            ＋
          </button>
          <span className="hs-zoom-value">{zoom}%</span>
        </div>
      </div>

      <TransportBar
        snapshot={snapshot}
        transport={transport}
        onToggleLoop={onToggleLoop}
        onClearRegion={() => adapterRef.current?.clearSelection()}
        onPlaySelection={() => void adapterRef.current?.playSelection()}
        follow={follow}
        followSuspended={followSuspended}
        onToggleFollow={onToggleFollow}
        onResumeFollow={resumeFollow}
        hasSelection={hasSelection}
      />

      <WaveformView
        onAdapter={onAdapter}
        onWaveformSeek={onWaveformSeek}
        onUserPanDuringPlayback={suspendFollow}
      />
      <p className="hint">{spikeCopy.waveformClickHint}</p>

      <div className="hs-statusbar" role="status">
        <span>
          {spikeCopy.currentMeasure}: {currentMeasure !== null ? `第${currentMeasure}小節` : '—'}
        </span>
        <span>
          {spikeCopy.activeNotes}:{' '}
          {activeCanonicals.size > 0 ? [...activeCanonicals].sort().join('、') : spikeCopy.noActiveNotes}
        </span>
        <span>
          {spikeCopy.loopPassage}:{' '}
          {loopMeasures.length > 0
            ? `第${loopMeasures[0]}–${loopMeasures.at(-1)}小節`
            : spikeCopy.noLoop}
        </span>
      </div>

      <main className="hs-main">
        <section className="hs-score-area">
          {initError ? (
            <div className="hs-error-panel" role="alert">
              <h2>{copy.renderFailed.title}</h2>
              <p>{initError}</p>
            </div>
          ) : renderError ? (
            <div className="hs-error-panel" role="alert">
              <h2>{copy.renderFailed.title}</h2>
              <p>{copy.renderFailed.body}</p>
              <button type="button" onClick={() => renderScore(view, zoom, fixtureId)}>
                {copy.renderFailed.actions.retry}
              </button>
            </div>
          ) : pages.length === 0 ? (
            <p className="hs-loading">{spikeCopy.loadingScore}…</p>
          ) : (
            <ScoreView
              ref={scoreRef}
              pages={pages}
              ariaLabel={copy.a11y.scoreRegion}
              onElementClick={(id) => selectExportId(id)}
              onUserNavigate={suspendFollow}
            />
          )}
          <p className="hint">{spikeCopy.scoreClickHint}</p>
          {followSuspended && (
            <p className="follow-note" role="status">
              {t('transport.followPaused')}{' '}
              <button type="button" className="resume-follow" onClick={resumeFollow}>
                {t('transport.resumeFollow')}
              </button>
            </p>
          )}
        </section>

        <aside className="hs-side">
          <section aria-label={spikeCopy.selectionHeading}>
            <h2 className="hs-panel-title">{spikeCopy.selectionHeading}</h2>
            {selection === null ? (
              <p className="hs-dim">{spikeCopy.selectionEmpty}</p>
            ) : (
              <dl className="hs-props">
                <dt>{spikeCopy.canonicalId}</dt>
                <dd>
                  <code>{selection.canonicalId ?? spikeCopy.selectionRest}</code>
                </dd>
                <dt>{spikeCopy.exportId}</dt>
                <dd>
                  <code>{selection.exportId}</code>
                </dd>
                {selectedNote && (
                  <>
                    <dt>{spikeCopy.pitchField}</dt>
                    <dd>
                      {selectedNote.isRest ? '—' : pitchLabel(selectedNote)}{' '}
                      {describeNote(selectedNote)}
                    </dd>
                  </>
                )}
                <dt>{spikeCopy.measureField}</dt>
                <dd>{selection.measure ?? '—'}</dd>
                <dt>{spikeCopy.onsetSec}</dt>
                <dd>{selection.onsetSec !== null ? `${selection.onsetSec.toFixed(3)} s` : '—'}</dd>
              </dl>
            )}
          </section>

          <MeasurePanel
            ready={ready}
            running={measuring}
            stage={measureStage}
            report={report}
            onRun={runMeasure}
          />
        </aside>
      </main>

      <footer className="hs-footer">
        <span>{t('app.privacyNote')}</span>
        <span className="hs-dim">Verovio {version}</span>
      </footer>
    </div>
  )
}

/**
 * Deterministic PCM synthesis for the UI-005 sync fixtures.
 *
 * The audio is generated *through the warp*: each canonical note's [onsetQl,
 * offsetQl) span is mapped to seconds via `warp.qlToSeconds`, so click
 * transients land exactly where the score says the note starts — including
 * under the non-linear beat-map warp. Same idea as UI-004's synth (pure
 * formula + LCG noise), reused deliberately; spikes may duplicate.
 *
 *  - every canonical note -> decaying sine at its (concert) midi pitch for
 *    its full sounding span — tie fragments produce ONE continuous tone
 *  - every onset -> short bright click transient (visible on the waveform)
 *  - rests -> silence (plus a hair of deterministic noise floor)
 */
import type { TimeWarp } from '../sync/timewarp'
import type { CanonicalSpan } from '../sync/syncMap'

export const FIXTURE_SAMPLE_RATE = 44100

const CLICK_S = 0.012
const CLICK_HZ = 2600
const ATTACK_S = 0.015
const RELEASE_S = 0.05
const MASTER_AMP = 0.6
const NOISE_AMP = 0.006

function lcg(seed: number): number {
  return (Math.imul(1103515245, seed) + 12345) >>> 0
}

const midiHz = (midi: number) => 440 * Math.pow(2, (midi - 69) / 12)

export interface SynthInput {
  /** canonical spans with midi pitch (concert presentation), pre-warp */
  notes: { span: CanonicalSpan; midi: number }[]
  warp: TimeWarp
  /** trailing silence after the last offset, seconds */
  tailSec?: number
  sampleRate?: number
}

/** Total audio length needed for a fixture (score end + tail). */
export function fixtureDurationSec(warp: TimeWarp, durationQl: import('../sync/rational').Rational, tailSec = 0.8): number {
  return warp.qlToSeconds(durationQl) + tailSec
}

export function synthScoreAudio(input: SynthInput): Float32Array {
  const sampleRate = input.sampleRate ?? FIXTURE_SAMPLE_RATE
  const tail = input.tailSec ?? 0.8
  // End of the last canonical span (or zero for an empty map).
  let lastEnd = 0
  const placed = input.notes.map(({ span, midi }) => {
    const start = input.warp.qlToSeconds(span.onsetQl)
    const end = input.warp.qlToSeconds(span.offsetQl)
    lastEnd = Math.max(lastEnd, end)
    return { start, end, midi }
  })
  const total = Math.floor((lastEnd + tail) * sampleRate)
  const out = new Float32Array(total)
  const twoPi = 2 * Math.PI

  for (const { start, end, midi } of placed) {
    const f = midiHz(midi)
    const i0 = Math.max(0, Math.round(start * sampleRate))
    const i1 = Math.min(total, Math.round(end * sampleRate))
    const attackN = Math.max(1, Math.round(ATTACK_S * sampleRate))
    const relN = Math.max(1, Math.round(RELEASE_S * sampleRate))
    for (let i = i0; i < i1; i += 1) {
      const t = i / sampleRate
      const phase = twoPi * f * t
      // fast attack, sustained body, short release — no click inside ties
      const a = Math.min(1, (i - i0) / attackN)
      const r = Math.min(1, (i1 - i) / relN)
      const env = a * r
      out[i] += (Math.sin(phase) + 0.3 * Math.sin(2 * phase)) * env * 0.45
    }
    // onset click: decaying high ping, clearly visible in the waveform
    const clickN = Math.min(total - i0, Math.round(CLICK_S * sampleRate))
    for (let i = 0; i < clickN; i += 1) {
      const u = i / clickN
      out[i0 + i] += Math.sin(twoPi * CLICK_HZ * (i / sampleRate)) * (1 - u) * 0.7
    }
  }

  // deterministic low noise floor so rests read as "quiet room", not digital zero
  let seed = 0x5157a9
  for (let i = 0; i < total; i += 1) {
    seed = lcg(seed)
    out[i] = Math.max(-1, Math.min(1, out[i] + (seed / (1 << 31) - 1) * NOISE_AMP))
  }
  for (let i = 0; i < total; i += 1) out[i] *= MASTER_AMP
  return out
}

/** Minimal PCM16 mono WAV encoder (RIFF), matching the Python fixtures. */

export function encodeWavPcm16Mono(samples: Float32Array, sampleRate: number): Blob {
  const dataBytes = samples.length * 2
  const buffer = new ArrayBuffer(44 + dataBytes)
  const view = new DataView(buffer)

  const writeStr = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i += 1) view.setUint8(offset + i, s.charCodeAt(i))
  }

  writeStr(0, 'RIFF')
  view.setUint32(4, 36 + dataBytes, true)
  writeStr(8, 'WAVE')
  writeStr(12, 'fmt ')
  view.setUint32(16, 16, true) // fmt chunk size
  view.setUint16(20, 1, true) // PCM
  view.setUint16(22, 1, true) // mono
  view.setUint32(24, sampleRate, true)
  view.setUint32(28, sampleRate * 2, true) // byte rate
  view.setUint16(32, 2, true) // block align
  view.setUint16(34, 16, true) // bit depth
  writeStr(36, 'data')
  view.setUint32(40, dataBytes, true)

  let offset = 44
  for (let i = 0; i < samples.length; i += 1) {
    const s = Math.max(-1, Math.min(1, samples[i]))
    view.setInt16(offset, Math.round(s * 32767), true)
    offset += 2
  }
  return new Blob([buffer], { type: 'audio/wav' })
}

import { forwardRef, useEffect } from 'react';
import type { RenderedPage } from '../score/verovio';
import { resolveHitElement } from '../score/domScore';

interface ScoreViewProps {
  pages: RenderedPage[];
  /** Called with the MusicXML export id (`hs-*`) of the clicked note/rest. */
  onElementClick: (exportId: string) => void;
  /**
   * User manually navigated the score (wheel / background-drag / scrollbar)
   * — the app treats this as "manual score navigation" and suspends follow.
   * Note clicks (`hs-*` targets) are selection, not navigation.
   */
  onUserNavigate?: () => void;
  ariaLabel: string;
}

/**
 * Renders Verovio's per-page SVG inside a scroll container. The raw SVG is
 * `aria-hidden` — selection details are mirrored in the side panel (the a11y
 * path never depends on raw SVG alone, GUI_UX_SPEC §24).
 *
 * Follow mode lives outside this component: the app calls
 * `el.scrollIntoView` on the active fragment; this view only reports when
 * the *user* scrolled, so follow can suspend instead of fighting.
 */
export const ScoreView = forwardRef<HTMLDivElement, ScoreViewProps>(function ScoreView(
  { pages, onElementClick, onUserNavigate, ariaLabel },
  ref,
) {
  useEffect(() => {
    const container = (ref as React.RefObject<HTMLDivElement>).current;
    if (!container || !onUserNavigate) return;
    const onWheel = () => onUserNavigate();
    const onPointerDown = (e: PointerEvent) => {
      // Scrollbar / paper background = navigation; a note hit = selection.
      const target = e.target as Element | null;
      if (target?.closest?.('[id^="hs-"]')) return;
      onUserNavigate();
    };
    container.addEventListener('wheel', onWheel, { passive: true });
    container.addEventListener('pointerdown', onPointerDown, { passive: true });
    return () => {
      container.removeEventListener('wheel', onWheel);
      container.removeEventListener('pointerdown', onPointerDown);
    };
  }, [ref, onUserNavigate]);

  const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const container = e.currentTarget;
    const hit = resolveHitElement(e.target, container);
    if (hit?.id) onElementClick(hit.id);
  };

  return (
    <div
      ref={ref}
      className="hs-score-scroll"
      role="region"
      aria-label={ariaLabel}
      onClick={handleClick}
    >
      <div className="hs-score-pages" aria-hidden="true">
        {pages.map((p) => (
          <div
            key={p.page}
            className="hs-score-page"
            data-page={p.page}
            dangerouslySetInnerHTML={{ __html: p.svg }}
          />
        ))}
      </div>
    </div>
  );
});

import { useEffect, useRef } from 'react'
import { t } from '../copy'
import type { TransportController } from '../transport/types'

export function formatClock(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) seconds = 0
  const m = Math.floor(seconds / 60)
  const s = Math.floor(seconds % 60)
  const ms = Math.floor((seconds % 1) * 1000)
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`
}

/**
 * Playhead time readout. Updates a DOM text node via rAF reading the
 * controller's audio clock directly — deliberately NOT React state, so the
 * app never re-renders at frame rate (GUI_UX_PLAN §10 TransportState rule).
 */
export function TimeReadout({ transport }: { transport: () => TransportController | null }) {
  const ref = useRef<HTMLSpanElement>(null)
  const transportRef = useRef(transport)
  transportRef.current = transport

  useEffect(() => {
    let raf = 0
    let last = ''
    const tick = () => {
      const c = transportRef.current()
      const text = c
        ? `${formatClock(c.getCurrentTime())} / ${formatClock(c.getDuration())}`
        : '--:--.--- / --:--.---'
      if (text !== last && ref.current) {
        ref.current.textContent = text
        last = text
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [])

  return (
    <span
      ref={ref}
      className="time-readout"
      role="status"
      aria-label={t('transport.timeDisplayAria')}
    />
  )
}

