import { useEffect, useRef } from 'react'
import HoverPlugin from 'wavesurfer.js/dist/plugins/hover.js'
import TimelinePlugin from 'wavesurfer.js/dist/plugins/timeline.js'
import { t } from '../copy'
import { WaveSurferTransportAdapter } from '../transport/wavesurferAdapter'
import { formatClock } from './TimeReadout'

interface Props {
  /** Called once the adapter exists (and again if it is rebuilt). */
  onAdapter: (adapter: WaveSurferTransportAdapter) => void
  /** User-initiated seek on the waveform (click). Seconds on the audio clock. */
  onWaveformSeek: (timeSec: number) => void
  /** User panned/dragged the waveform while follow+play were active. */
  onUserPanDuringPlayback: () => void
}

/**
 * View layer: mounts wavesurfer inside a WaveSurferTransportAdapter and
 * attaches view-only plugins (Hover, Timeline). Transport policy lives in
 * the adapter/core — this component never stores playhead time.
 */
export function WaveformView(props: Props) {
  const containerRef = useRef<HTMLDivElement>(null)
  const timelineRef = useRef<HTMLDivElement>(null)
  const propsRef = useRef(props)
  propsRef.current = props

  useEffect(() => {
    if (!containerRef.current) return
    const adapter = new WaveSurferTransportAdapter({
      container: containerRef.current,
      height: 104,
    })

    const ws = adapter.getWavesurfer()
    ws.registerPlugin(
      HoverPlugin.create({
        lineColor: '#3b73d9',
        labelBackground: '#20242c',
        labelColor: '#e8e8ea',
        labelSize: '11px',
        formatTimeCallback: (s) => formatClock(s),
      }),
    )
    if (timelineRef.current) {
      ws.registerPlugin(
        TimelinePlugin.create({
          container: timelineRef.current,
          formatTimeCallback: (s) => formatClock(s).slice(0, 5),
          style: { color: '#5f6672', fontSize: '10px' },
        }),
      )
    }

    const offWheel = adapter.attachWheelZoom()

    // Waveform click → audio seek is wavesurfer's own interaction; surface it
    // so the app can resolve the nearest canonical element (sync chain).
    const offInteraction = ws.on('interaction', (newTime: number) => {
      propsRef.current.onWaveformSeek(newTime)
    })

    // User *pan* (wheel/drag-scroll) while follow is active → suspend follow.
    // Deliberately NOT pointerdown: a click-to-seek must not suspend follow —
    // the score should jump to the new position and keep tracking.
    const wrapper = ws.getWrapper()
    const onUserNav = () => {
      if (adapter.core.isPlaying()) propsRef.current.onUserPanDuringPlayback()
    }
    wrapper.addEventListener('wheel', onUserNav, { passive: true })

    propsRef.current.onAdapter(adapter)
    return () => {
      offWheel()
      offInteraction()
      wrapper.removeEventListener('wheel', onUserNav)
      adapter.dispose()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <div className="waveform-area">
      <div
        ref={containerRef}
        className="waveform"
        role="region"
        aria-label={t('waveform.regionAria')}
      />
      <div ref={timelineRef} className="timeline" aria-hidden="true" />
    </div>
  )
}

import type { WaveSurferTransportAdapter } from '../transport/wavesurferAdapter'
import type { ScoreSyncEngine, TimeRangeSec } from '../sync/syncEngine'
import type { PitchView } from '../fixtures'

/**
 * In-page measurement harness for UI-005. All numbers are measured with
 * performance.now() against the media element clock — no "feels smooth".
 * Driven from the UI (計測パネル) or scripts/measure.mjs (puppeteer-core).
 *
 * The harness never reaches into React internals: the app exposes a narrow
 * {@link SyncHooks} surface whose DOM-touching functions are the same code
 * paths real clicks use.
 */
export interface SyncHooks {
  adapter: WaveSurferTransportAdapter
  engine: ScoreSyncEngine
  /** Score-click path: export/canonical id -> onset -> transport.seek (awaits 'seeked'). */
  clickCanonical(canonicalId: string): Promise<void>
  /** Waveform-click path: audio seconds -> nearest canonical -> DOM mark. */
  selectAtSeconds(timeSec: number): void
  /** Currently marked hs-active canonical ids (DOM truth). */
  domActiveCanonicals(): Set<string>
  /** Currently marked hs-loop canonical ids (DOM truth). */
  domLoopCanonicals(): Set<string>
  /** Canonical id of the current selection, or null. */
  selectedCanonical(): string | null
  /** Programmatic view switch; resolves after re-render + marks reapplied. */
  switchView(view: PitchView): Promise<void>
  /** App component render counter (React-render discipline check). */
  getRenderCount(): number
  /** Verovio renderToSVG call counter (no-per-frame-render check). */
  getVerovioRenderCalls(): number
  /** Wall ms spent inside the follow scroll handler (drained per run). */
  drainFollowScrollMs(): number[]
  /** Wall ms spent inside the DOM highlight applier (drained per run). */
  drainHighlightMs(): number[]
}

export interface LatencyStats {
  samples: number
  medianMs: number
  p95Ms: number
  meanMs: number
  maxMs: number
}

export interface SyncErrorStats {
  /** rAF frames sampled during playback. */
  frames: number
  /** Frames where DOM hs-active set != expected canonical set. */
  mismatchFrames: number
  /** Active-note boundaries crossed during the window. */
  boundaries: number
  /** |audio clock at DOM update − boundary time| per transition. */
  lagMeanMs: number
  lagMaxMs: number
  /** React renders during the same window. */
  reactRenders: number
  /** Verovio renderToSVG calls during the same window (must be 0). */
  verovioRenderCalls: number
}

export interface LoopDriftStats {
  wraps: number
  loopStart: number
  loopEnd: number
  rate: number
  overshootMeanMs: number
  overshootMaxMs: number
  periodErrMeanMs: number
  periodErrMaxMs: number
  totalDriftMs: number
}

export interface LoopScoreStats {
  rangeSec: { start: number; end: number }
  expected: string[]
  domMarked: string[]
  correct: boolean
  measures: number[]
}

export interface ViewSwitchStats {
  from: PitchView
  to: PitchView
  switchMs: number
  selectionPreserved: boolean
  /** |audio clock after switch − expected continuity| — should be ~0 paused,
   *  ≈ elapsed wall while playing (clock must never reset). */
  timeConsistencyMs: number
  playingContinued: boolean
  loopPreserved: boolean
}

export interface SyncReport {
  fixture: string
  warpMode: string
  durationSec: number
  canonicalNotes: number
  scoreClickSeek: LatencyStats
  waveClickSelect: LatencyStats & { correctSelections: number }
  sync: SyncErrorStats
  follow: { calls: number; meanMs: number; maxMs: number }
  highlight: { calls: number; meanMs: number; maxMs: number }
  loopDrift: LoopDriftStats
  loopScore: LoopScoreStats
  viewSwitch: ViewSwitchStats
}

export interface FullReport {
  tool: 'ui-005-spike'
  timestamp: string
  userAgent: string
  fixtures: SyncReport[]
}

// ---- helpers ---------------------------------------------------------------

const now = () => performance.now()
const nextFrame = () => new Promise<number>((r) => requestAnimationFrame(r))
const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms))

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b)
  const m = Math.floor(s.length / 2)
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2
}

function percentile(xs: number[], p: number): number {
  const s = [...xs].sort((a, b) => a - b)
  const i = Math.min(s.length - 1, Math.max(0, Math.ceil((p / 100) * s.length) - 1))
  return s[i]
}

function mean(xs: number[]): number {
  return xs.reduce((a, b) => a + b, 0) / Math.max(1, xs.length)
}

function latency(xs: number[]): LatencyStats {
  return {
    samples: xs.length,
    medianMs: median(xs),
    p95Ms: percentile(xs, 95),
    meanMs: mean(xs),
    maxMs: Math.max(0, ...xs),
  }
}

const sortedSet = (s: ReadonlySet<string>) => [...s].sort()

// ---- measurements -----------------------------------------------------------

/** Score click -> audio seek: canonical id -> onset seconds -> seek(). */
async function measureScoreClickSeek(hooks: SyncHooks): Promise<LatencyStats> {
  const ids = hooks.engine.canonicalIds()
  const xs: number[] = []
  for (const id of ids) {
    const t0 = now()
    await hooks.clickCanonical(id)
    xs.push(now() - t0)
    await nextFrame()
  }
  return latency(xs)
}

/**
 * Waveform click -> score context: audio time -> nearest canonical -> DOM
 * mark. Also verifies the selected canonical equals the engine's nearest.
 */
async function measureWaveClickSelect(
  hooks: SyncHooks,
): Promise<LatencyStats & { correctSelections: number }> {
  const duration = hooks.adapter.getDuration()
  const xs: number[] = []
  let correct = 0
  for (let i = 0; i < 24; i += 1) {
    const u = ((i * 7919) % 1000) / 1000
    const t = 0.3 + u * Math.max(0, duration - 0.6)
    const expected = hooks.engine.nearestCanonicalAtSeconds(t)?.canonicalId ?? null
    const t0 = now()
    hooks.selectAtSeconds(t)
    xs.push(now() - t0)
    if (expected !== null && hooks.selectedCanonical() === expected) correct += 1
    await nextFrame()
  }
  return { ...latency(xs), correctSelections: correct }
}

/**
 * Playback sync error: sample the audio clock each rAF, compute the expected
 * active canonical set, and compare with the DOM hs-active set. Transition
 * lag = audio-clock delta between an expected boundary crossing and the
 * frame where the DOM set matches it.
 */
async function measureSyncError(
  hooks: SyncHooks,
  seconds = 6,
): Promise<SyncErrorStats> {
  const { adapter, engine } = hooks
  adapter.pause()
  await adapter.seek(0.05)
  const renders0 = hooks.getRenderCount()
  const renderCalls0 = hooks.getVerovioRenderCalls()

  interface Sample {
    audioT: number
    expected: Set<string>
    dom: Set<string>
  }
  const samples: Sample[] = []
  await adapter.play()
  const deadline = now() + seconds * 1000
  while (now() < deadline) {
    await nextFrame()
    const audioT = adapter.getCurrentTime()
    samples.push({
      audioT,
      expected: engine.activeAtSeconds(audioT),
      dom: hooks.domActiveCanonicals(),
    })
  }
  adapter.pause()
  const renders1 = hooks.getRenderCount()
  const renderCalls1 = hooks.getVerovioRenderCalls()

  let mismatchFrames = 0
  const lags: number[] = []
  let prevExpected: Set<string> | null = null
  let pendingBoundary: { audioT: number; expected: Set<string> } | null = null
  for (const s of samples) {
    if (prevExpected !== null && !setEq(s.expected, prevExpected)) {
      // expected set changed at this audio time — a note boundary
      pendingBoundary = { audioT: s.audioT, expected: s.expected }
    }
    if (pendingBoundary && setEq(s.dom, pendingBoundary.expected)) {
      lags.push((s.audioT - pendingBoundary.audioT) * 1000)
      pendingBoundary = null
    }
    if (!setEq(s.dom, s.expected)) mismatchFrames += 1
    prevExpected = s.expected
  }
  // frames counted while a transition was in flight are expected lag, not errors;
  // honest accounting: report both raw mismatch count and transition count.
  return {
    frames: samples.length,
    mismatchFrames,
    boundaries: lags.length,
    lagMeanMs: mean(lags),
    lagMaxMs: Math.max(0, ...lags),
    reactRenders: renders1 - renders0,
    verovioRenderCalls: renderCalls1 - renderCalls0,
  }
}

function setEq(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false
  for (const v of a) if (!b.has(v)) return false
  return true
}

/** Loop wrap drift — same method as UI-004 (wrap overshoot + period error). */
async function measureLoopDrift(
  hooks: SyncHooks,
  wraps = 8,
): Promise<LoopDriftStats> {
  const { adapter } = hooks
  const duration = adapter.getDuration()
  const loopLen = Math.min(1.5, duration * 0.2)
  const start = Math.max(0.5, duration * 0.25)
  const end = start + loopLen
  const rate = 1.5

  const wrapWall: number[] = []
  const overshoots: number[] = []
  adapter.setRate(rate)
  adapter.setLoop({ start, end })
  await adapter.seek(start + 0.01)

  return await new Promise<LoopDriftStats>((resolve) => {
    const detach = adapter.onLoopWrap((info) => {
      wrapWall.push(now())
      overshoots.push(info.overshoot * 1000)
    })
    void adapter.play()
    const expectedPeriodMs = ((end - start) / rate) * 1000
    const timer = setInterval(() => {
      if (wrapWall.length >= wraps) {
        clearInterval(timer)
        detach()
        adapter.pause()
        adapter.setLoop(null)
        adapter.setRate(1)
        const errs = wrapWall.slice(1).map((w, i) => w - wrapWall[i] - expectedPeriodMs)
        resolve({
          wraps: wrapWall.length,
          loopStart: start,
          loopEnd: end,
          rate,
          overshootMeanMs: mean(overshoots),
          overshootMaxMs: Math.max(0, ...overshoots),
          periodErrMeanMs: mean(errs),
          periodErrMaxMs: Math.max(0, ...errs.map(Math.abs)),
          totalDriftMs:
            wrapWall.length > 1
              ? wrapWall.at(-1)! - wrapWall[0] - expectedPeriodMs * (wrapWall.length - 1)
              : 0,
        })
      }
    }, 30)
  })
}

/**
 * Loop -> score passage: arm a known range, then compare the DOM hs-loop
 * marks with the engine's overlap set (exact set equality).
 */
async function measureLoopScore(hooks: SyncHooks): Promise<LoopScoreStats> {
  const { adapter, engine } = hooks
  const duration = adapter.getDuration()
  // A range that crosses measure boundaries and the sn-000012 tie:
  // onset of sn-000010 (m.3) through the offset of sn-000019 (m.5) — resolved
  // through the warp so it exercises the non-linear map too.
  const range: TimeRangeSec = {
    start: engine.secondsRangeForCanonical('sn-000010')?.start ?? duration * 0.25,
    end: engine.secondsRangeForCanonical('sn-000019')?.end ?? duration * 0.5,
  }
  adapter.setLoop(range)
  await nextFrame()
  await nextFrame()
  const expected = engine.canonicalsInRange(range)
  const domMarked = hooks.domLoopCanonicals()
  const measures = engine.measuresInRange(range).map((m) => m.number)
  adapter.setLoop(null)
  return {
    rangeSec: range,
    expected: sortedSet(expected),
    domMarked: sortedSet(domMarked),
    correct: setEq(expected, domMarked),
    measures,
  }
}

/** Concert↔Horn while playing: selection, transport, loop must be preserved. */
async function measureViewSwitch(hooks: SyncHooks): Promise<ViewSwitchStats> {
  const { adapter } = hooks
  // Arm a loop so its preservation is part of the check.
  const loopRange: TimeRangeSec = {
    start: adapter.getDuration() * 0.2,
    end: adapter.getDuration() * 0.4,
  }
  adapter.setLoop(loopRange)
  // Select a tied note — the interesting multi-fragment case.
  hooks.selectAtSeconds(
    hooks.engine.secondsForCanonical('sn-000012') ?? adapter.getDuration() * 0.3,
  )
  await adapter.seek(adapter.getDuration() * 0.3)
  await adapter.play()
  await sleep(400)
  const t0 = now()
  const audioBefore = adapter.getCurrentTime()
  await hooks.switchView('horn')
  const switchMs = now() - t0
  const audioAfter = adapter.getCurrentTime()
  const expectedAudio = audioBefore + switchMs / 1000
  const snap = adapter.getSnapshot()
  const stats: ViewSwitchStats = {
    from: 'concert',
    to: 'horn',
    switchMs,
    selectionPreserved: hooks.selectedCanonical() === 'sn-000012',
    timeConsistencyMs: Math.abs(audioAfter - expectedAudio) * 1000,
    playingContinued: snap.status === 'playing',
    loopPreserved:
      snap.loop !== null &&
      Math.abs(snap.loop.start - loopRange.start) < 0.01 &&
      Math.abs(snap.loop.end - loopRange.end) < 0.01,
  }
  // settle, switch back, stop loop
  await sleep(300)
  await hooks.switchView('concert')
  adapter.pause()
  adapter.setLoop(null)
  return stats
}

// ---- orchestration ----------------------------------------------------------

export interface RunOptions {
  hooks: SyncHooks
  fixtureLabel: string
  warpMode: string
  onProgress?: (stage: string) => void
}

export async function runMeasurements(opts: RunOptions): Promise<SyncReport> {
  const { hooks } = opts
  const progress = opts.onProgress ?? (() => {})
  const { adapter, engine } = hooks
  adapter.pause()

  progress('楽譜クリック→シーク')
  const scoreClickSeek = await measureScoreClickSeek(hooks)

  progress('波形クリック→ハイライト')
  const waveClickSelect = await measureWaveClickSelect(hooks)

  progress('追従＋同期誤差')
  hooks.drainFollowScrollMs()
  hooks.drainHighlightMs()
  const sync = await measureSyncError(hooks, 6)
  const followSamples = hooks.drainFollowScrollMs()
  const hlSamples = hooks.drainHighlightMs()

  progress('ループ')
  const loopDrift = await measureLoopDrift(hooks)
  const loopScore = await measureLoopScore(hooks)

  progress('表示切替')
  const viewSwitch = await measureViewSwitch(hooks)

  adapter.pause()
  return {
    fixture: opts.fixtureLabel,
    warpMode: opts.warpMode,
    durationSec: adapter.getDuration(),
    canonicalNotes: engine.canonicalIds().length,
    scoreClickSeek,
    waveClickSelect,
    sync,
    follow: {
      calls: followSamples.length,
      meanMs: mean(followSamples),
      maxMs: Math.max(0, ...followSamples),
    },
    highlight: {
      calls: hlSamples.length,
      meanMs: mean(hlSamples),
      maxMs: Math.max(0, ...hlSamples),
    },
    loopDrift,
    loopScore,
    viewSwitch,
  }
}

/**
 * DOM-side helpers for the rendered Verovio SVG.
 *
 * Verovio mirrors the MusicXML `note/@id` onto the rendered element
 * (`<g class="note" id="hs-sn-000003">`), so a rendered element can be looked
 * up by export id and resolved to a canonical `sn-*` id. Highlighting is a
 * pure `classList` toggle — no re-render (measured in the spike results).
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlNoteId } from './ids';

export interface ElementIndex {
  /** export id (`hs-sn-000003-2`) → rendered <g> element */
  byExportId: Map<string, Element>;
  /** canonical id (`sn-000003`) → all rendered fragments */
  byCanonical: Map<string, Element[]>;
  noteCount: number;
}

export const SELECTED_CLASS = 'hs-selected';
export const ACTIVE_CLASS = 'hs-active';
export const HIT_CLASS = 'hs-hit';
/** Loop-passage indication: applied to every rendered fragment of canonical
 *  notes whose span overlaps the armed A-B loop. */
export const LOOP_CLASS = 'hs-loop';
/** Subtle wash on the measure <g> containing an active note. */
export const MEASURE_ACTIVE_CLASS = 'hs-measure-active';

const SVG_NS = 'http://www.w3.org/2000/svg';

/**
 * Append an invisible hit ellipse over each note/rest glyph.
 *
 * Finding (UI-003): Verovio paints noteheads as font glyphs, and a hollow
 * notehead (half/whole note) is *transparent in the middle* — a click at its
 * centre falls through to the <svg> background. Relying on glyph paint for
 * hit-testing is therefore unreliable; the production-safe pattern is an
 * explicit transparent overlay inside each id-bearing group.
 */
function addHitShape(el: Element): void {
  if (typeof (el as SVGGElement).getBBox !== 'function') return; // jsdom etc.
  try {
    const head = el.querySelector('.notehead') ?? el.querySelector('use') ?? el;
    const box = (head as SVGGElement).getBBox();
    if (!box || box.width <= 0 || box.height <= 0) return;
    const pad = Math.max(box.width, box.height) * 0.35;
    const hit = document.createElementNS(SVG_NS, 'ellipse');
    hit.setAttribute('cx', String(box.x + box.width / 2));
    hit.setAttribute('cy', String(box.y + box.height / 2));
    hit.setAttribute('rx', String(box.width / 2 + pad));
    hit.setAttribute('ry', String(box.height / 2 + pad));
    hit.setAttribute('class', HIT_CLASS);
    // Append inside the notehead group so the ellipse shares the glyph's
    // coordinate space; closest('[id^=hs-]') still resolves the note group.
    head.appendChild(hit);
  } catch {
    /* getBBox unsupported — skip hit shape (non-browser env) */
  }
}

/** Index every Verovio element carrying a HornScribe export id. */
export function buildElementIndex(container: Element): ElementIndex {
  const byExportId = new Map<string, Element>();
  const byCanonical = new Map<string, Element[]>();
  let noteCount = 0;
  for (const el of Array.from(container.querySelectorAll('[id^="hs-"]'))) {
    const id = el.id;
    if (!isMusicxmlNoteId(id) && !id.startsWith('hs-rest-')) continue;
    byExportId.set(id, el);
    addHitShape(el);
    const canonical = canonicalNoteIdFromMusicxml(id);
    if (canonical) {
      noteCount++;
      const list = byCanonical.get(canonical) ?? [];
      list.push(el);
      byCanonical.set(canonical, list);
    }
  }
  return { byExportId, byCanonical, noteCount };
}

/** Hit-test a click target up to the note/rest group carrying the id. */
export function resolveHitElement(target: EventTarget | null, container: Element): Element | null {
  if (!(target instanceof Element)) return null;
  const hit = target.closest('[id^="hs-"]');
  return hit && container.contains(hit) ? hit : null;
}

function setClass(elements: Iterable<Element>, cls: string, on: boolean): number {
  let n = 0;
  for (const el of elements) {
    el.classList.toggle(cls, on);
    n++;
  }
  return n;
}

/** Clear then apply `cls` to every rendered fragment of `canonicalId`. */
export function markCanonical(
  index: ElementIndex,
  canonicalId: string | null,
  cls: string,
): number {
  for (const el of Array.from(index.byExportId.values())) el.classList.remove(cls);
  if (!canonicalId) return 0;
  return setClass(index.byCanonical.get(canonicalId) ?? [], cls, true);
}

/** Apply `cls` to a set of canonical ids without clearing the selection class. */
export function markCanonicalSet(
  index: ElementIndex,
  canonicalIds: ReadonlySet<string>,
  cls: string,
): number {
  for (const el of Array.from(index.byExportId.values())) el.classList.remove(cls);
  let n = 0;
  for (const id of canonicalIds) n += setClass(index.byCanonical.get(id) ?? [], cls, true);
  return n;
}

/**
 * The rendered measure group containing an element — Verovio wraps each
 * measure in `<g class="measure">` (random id). Used for the "current
 * measure" wash; the id itself is never treated as identity (UI-003 finding:
 * non-`hs-*` ids are unstable), the element is re-resolved every mark.
 */
export function measureElementOf(el: Element): Element | null {
  return el.closest('g.measure');
}

const WASH_CLASS = 'hs-measure-wash';

/**
 * Toggle `cls` on the measure groups containing the given elements, and (in
 * browsers, where getBBox exists) maintain a `<rect class="hs-measure-wash">`
 * background covering the measure's extent — the "current measure subtle
 * wash" of GUI_UX_SPEC §10 without touching any glyph.
 */
export function markMeasures(
  container: Element,
  elements: Iterable<Element>,
  cls: string,
  on: boolean,
): number {
  const measures = new Set<Element>();
  for (const el of elements) {
    const m = measureElementOf(el);
    if (m) measures.add(m);
  }
  let n = 0;
  for (const m of Array.from(container.querySelectorAll('g.measure'))) {
    const target = on && measures.has(m);
    if (m.classList.contains(cls) !== target) {
      m.classList.toggle(cls, target);
      let wash = m.querySelector(`:scope > rect.${WASH_CLASS}`);
      if (target && !wash && typeof (m as SVGGElement).getBBox === 'function') {
        try {
          const box = (m as SVGGElement).getBBox();
          wash = document.createElementNS(SVG_NS, 'rect');
          wash.setAttribute('x', String(box.x));
          wash.setAttribute('y', String(box.y));
          wash.setAttribute('width', String(box.width));
          wash.setAttribute('height', String(box.height));
          wash.setAttribute('class', WASH_CLASS);
          m.insertBefore(wash, m.firstChild);
        } catch {
          /* getBBox unsupported — class mark still applied */
        }
      } else if (!target && wash) {
        wash.remove();
      }
    }
    if (target) n++;
  }
  return n;
}

/**
 * TypeScript mirror of the FND-001 identity rules
 * (`python/hornscribe/domain/ids.py`, `docs/CONTRACTS.md` §1).
 *
 *   canonical note        sn-<6 digits>
 *   MusicXML note/@id     hs-sn-<6 digits>
 *   MusicXML tied fragment hs-sn-<6 digits>-<k>   (k > 1)
 *   MusicXML rest          hs-rest-<6 digits>     (presentation-only)
 *
 * Every `hs-sn-*` export id — fragment or not — resolves back to exactly one
 * `sn-*` canonical note id. `hs-rest-*` deliberately has no canonical target.
 */

const SCORE_NOTE_RE = /^sn-\d{6}$/;
const MUSICXML_NOTE_RE = /^hs-sn-\d{6}(?:-\d+)?$/;
const MUSICXML_REST_RE = /^hs-rest-\d{6}$/;
const CANONICAL_PART_RE = /^hs-(sn-\d{6})/;

export function isScoreNoteId(value: string): boolean {
  return SCORE_NOTE_RE.test(value);
}

export function isMusicxmlNoteId(value: string): boolean {
  return MUSICXML_NOTE_RE.test(value);
}

export function isMusicxmlRestId(value: string): boolean {
  return MUSICXML_REST_RE.test(value);
}

/** `sn-000042` -> `hs-sn-000042` (fragment 1), `hs-sn-000042-2` (fragment 2), … */
export function musicxmlNoteId(canonicalId: string, fragment = 1): string {
  if (!isScoreNoteId(canonicalId)) {
    throw new Error(`not a canonical score note id: ${canonicalId}`);
  }
  if (fragment < 1) {
    throw new Error(`fragment must be >= 1, got ${fragment}`);
  }
  return fragment === 1 ? `hs-${canonicalId}` : `hs-${canonicalId}-${fragment}`;
}

/**
 * `hs-sn-000042` -> `sn-000042`; `hs-sn-000042-3` -> `sn-000042`.
 * Returns null for anything that is not a canonical-backed export id
 * (e.g. `hs-rest-*`, or a Verovio-generated id like `d1e123`).
 */
export function canonicalNoteIdFromMusicxml(exportId: string): string | null {
  if (!isMusicxmlNoteId(exportId)) return null;
  const match = CANONICAL_PART_RE.exec(exportId);
  return match ? match[1] : null;
}

/**
 * MusicXML → flat note/rest model used for the parallel accessible score
 * representation (GUI_UX_PLAN §40: a11y must not depend on raw SVG alone).
 * This is a presentation helper only — canonical identity still comes from
 * `hs-sn-*` ids, not from parse order.
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlRestId } from './ids';

export interface ParsedNote {
  exportId: string; // MusicXML note/@id, e.g. hs-sn-000003-2 / hs-rest-000001
  canonicalId: string | null; // sn-000003, or null for rests
  isRest: boolean;
  measure: number;
  step?: string;
  alter?: number;
  octave?: number;
  type?: string;
  dots: number;
  /** This note is a member of a tie chain (start/stop). */
  tied: boolean;
}

export interface ScoreDoc {
  title: string;
  notes: ParsedNote[];
  measureCount: number;
}

const TYPE_JA: Record<string, string> = {
  whole: '全',
  half: '二分',
  quarter: '四分',
  eighth: '八分',
  '16th': '十六分',
  '32nd': '三十二分',
  '64th': '六十四分',
};

export function noteTypeJa(note: ParsedNote): string {
  const base = TYPE_JA[note.type ?? ''] ?? (note.type ?? '');
  const dotted = note.dots > 0 ? '付点' : '';
  const unit = note.isRest ? '休符' : '音符';
  return `${dotted}${base}${unit}`.replace(/^付点$/, '');
}

export function pitchLabel(note: ParsedNote): string {
  if (note.isRest || note.step === undefined || note.octave === undefined) return '';
  const acc = note.alter === undefined || note.alter === 0 ? '' : note.alter > 0 ? '♯'.repeat(note.alter) : '♭'.repeat(-note.alter);
  return `${note.step}${acc}${note.octave}`;
}

/** e.g. "第3小節 B♭3 付点四分音符 (sn-000003)" / "第2小節 四分休符" */
export function describeNote(note: ParsedNote): string {
  const where = `第${note.measure}小節`;
  if (note.isRest) return `${where} ${noteTypeJa(note)}`;
  const pitch = pitchLabel(note);
  const tie = note.tied ? '・タイ' : '';
  return `${where} ${pitch} ${noteTypeJa(note)}${tie}`;
}

export function parseScoreDoc(xml: string): ScoreDoc {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  const title =
    doc.querySelector('movement-title')?.textContent?.trim() ||
    doc.querySelector('work-title')?.textContent?.trim() ||
    '';
  const notes: ParsedNote[] = [];
  let measureCount = 0;
  for (const measure of Array.from(doc.querySelectorAll('part > measure'))) {
    const number = Number(measure.getAttribute('number') ?? measureCount + 1);
    measureCount = Math.max(measureCount, Number.isFinite(number) ? number : measureCount + 1);
    for (const noteEl of Array.from(measure.querySelectorAll(':scope > note'))) {
      const exportId = noteEl.getAttribute('id') ?? '';
      const isRest = noteEl.querySelector('rest') !== null || isMusicxmlRestId(exportId);
      const pitchEl = noteEl.querySelector('pitch');
      const alterText = pitchEl?.querySelector('alter')?.textContent;
      const tied =
        noteEl.querySelector('tie[type="start"], tie[type="stop"]') !== null ||
        noteEl.querySelector('notations > tied') !== null;
      notes.push({
        exportId,
        canonicalId: canonicalNoteIdFromMusicxml(exportId),
        isRest,
        measure: number,
        step: pitchEl?.querySelector('step')?.textContent ?? undefined,
        alter: alterText !== undefined && alterText !== null ? Number(alterText) : undefined,
        octave: pitchEl?.querySelector('octave')?.textContent
          ? Number(pitchEl.querySelector('octave')!.textContent)
          : undefined,
        type: noteEl.querySelector('type')?.textContent ?? undefined,
        dots: noteEl.querySelectorAll('dot').length,
        tied,
      });
    }
  }
  return { title, notes, measureCount };
}

/**
 * Thin wrapper around the Verovio WASM toolkit used by the spike.
 *
 * `verovio/wasm` inlines the WASM binary inside `dist/verovio-module.mjs`, so
 * module instantiation needs no network fetch and no .wasm asset pipeline —
 * that property is what keeps the spike (and later the Tauri shell) fully
 * offline without CSP workarounds beyond the script bundle itself.
 */
import createVerovioModule, { type VerovioModule } from 'verovio/wasm';
import {
  VerovioToolkit,
  type VerovioElementsAtTime,
  type VerovioTimemapEntry,
  type VerovioTimesForElement,
} from 'verovio/esm';

export interface RenderedPage {
  page: number;
  svg: string;
}

/** Spike instrumentation: total renderToSVG calls since module load. The
 *  playback/highlight path must never increment this (UI-005 criterion). */
export const renderStats = { renderToSVGCalls: 0 };

/** Baseline engraving options. `pageHeight` is short on purpose so the
 *  multi-system fixture paginates and `getPageWithElement` is exercised. */
const BASE_OPTIONS = {
  pageWidth: 2100,
  pageHeight: 1100,
  scale: 40,
  adjustPageHeight: false,
  footer: 'none',
  breaks: 'auto',
} as const;

export class ScoreRenderer {
  private toolkit: VerovioToolkit | null = null;
  private zoomPct = 100;

  get version(): string {
    return this.toolkit?.getVersion() ?? 'unknown';
  }

  async init(): Promise<void> {
    if (this.toolkit) return;
    const mod: VerovioModule = await createVerovioModule();
    this.toolkit = new VerovioToolkit(mod);
    this.toolkit.setOptions({ ...BASE_OPTIONS });
  }

  private tk(): VerovioToolkit {
    if (!this.toolkit) throw new Error('ScoreRenderer not initialized');
    return this.toolkit;
  }

  /** Returns true when Verovio accepted the document. */
  load(musicXml: string): boolean {
    return this.tk().loadData(musicXml);
  }

  setZoom(pct: number): void {
    this.zoomPct = pct;
    this.tk().setOptions({
      ...BASE_OPTIONS,
      // Verovio `scale` is a percent-like zoom factor (default 40). Pagination
      // is stable across scale changes because page size scales with it.
      scale: Math.max(10, Math.round((40 * pct) / 100)),
    });
  }

  getZoom(): number {
    return this.zoomPct;
  }

  pageCount(): number {
    return this.tk().getPageCount();
  }

  /** Render every page; page index is 1-based like `renderToSVG`.
   *  Page 1 is rendered first so the layout (and therefore `getPageCount`)
   *  reflects the current options before counting. */
  renderAllPages(): RenderedPage[] {
    const tk = this.tk();
    const first = tk.renderToSVG(1);
    renderStats.renderToSVGCalls += 1;
    const count = tk.getPageCount();
    const pages: RenderedPage[] = [{ page: 1, svg: first }];
    for (let page = 2; page <= count; page++) {
      pages.push({ page, svg: tk.renderToSVG(page) });
      renderStats.renderToSVGCalls += 1;
    }
    return pages;
  }

  /** Parsed timemap; must be (re)built after each `load`.
   *  verovio >= 4.x returns an already-parsed array (the ESM wrapper
   *  JSON.parses internally); older builds returned a raw string — accept both. */
  timemap(): VerovioTimemapEntry[] {
    const raw = this.tk().renderToTimemap() as unknown;
    if (typeof raw === 'string') return JSON.parse(raw) as VerovioTimemapEntry[];
    return raw as VerovioTimemapEntry[];
  }

  durationMs(): number {
    const map = this.timemap();
    let max = 0;
    for (const entry of map) max = Math.max(max, entry.tstamp);
    return max;
  }

  /** ms onset for an element id (e.g. `hs-sn-000003-2`), or null if unknown. */
  timeForElement(id: string): number | null {
    try {
      const t = this.tk().getTimeForElement(id);
      return Number.isFinite(t) && t >= 0 ? t : null;
    } catch {
      return null;
    }
  }

  timesForElement(id: string): VerovioTimesForElement | null {
    try {
      return this.tk().getTimesForElement(id);
    } catch {
      return null;
    }
  }

  elementsAtTime(ms: number): VerovioElementsAtTime | null {
    try {
      return this.tk().getElementsAtTime(ms);
    } catch {
      return null;
    }
  }

  /** 1-based page containing the element, 0 when not found. */
  pageWithElement(id: string): number {
    try {
      return this.tk().getPageWithElement(id);
    } catch {
      return 0;
    }
  }
}

/** Lazy singleton — survives React StrictMode double-mount and hot reloads. */
let rendererPromise: Promise<ScoreRenderer> | null = null;
export function getScoreRenderer(): Promise<ScoreRenderer> {
  if (!rendererPromise) {
    const renderer = new ScoreRenderer();
    rendererPromise = renderer.init().then(() => renderer);
  }
  return rendererPromise;
}

/* UI-005 spike styles — HornScribe design tokens (GUI_UX_PLAN §33, light). */
:root {
  --hs-bg-app: #f3f4f6;
  --hs-surface-1: #ffffff;
  --hs-surface-2: #f8f9fb;
  --hs-surface-3: #eef1f5;
  --hs-border-subtle: #dadde3;
  --hs-text-primary: #1b1d22;
  --hs-text-secondary: #5f6672;
  --hs-accent: #3b73d9;
  --hs-accent-hover: #2f64c4;
  --hs-active: #b45309; /* playback-active mark (amber, distinct from selection) */
  --hs-loop: #2f7d4f; /* loop passage indication (green) */
  --hs-score-paper: #fbfaf7;
  font-family: 'Segoe UI Variable', 'Segoe UI', 'Yu Gothic UI', 'Meiryo', sans-serif;
  color: var(--hs-text-primary);
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--hs-bg-app); }

.hs-app { display: flex; flex-direction: column; min-height: 100vh; }

.hs-header {
  padding: 10px 16px 6px;
  border-bottom: 1px solid var(--hs-border-subtle);
  background: var(--hs-surface-1);
}
.hs-header h1 { font-size: 16px; margin: 0; }
.hs-subtitle { margin: 3px 0 0; font-size: 12px; color: var(--hs-text-secondary); }

.hs-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  padding: 8px 16px;
  background: var(--hs-surface-1);
  border-bottom: 1px solid var(--hs-border-subtle);
}
.hs-field { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; }
.hs-field select { font-size: 13px; padding: 4px 8px; }

.hs-segment { display: inline-flex; border: 1px solid var(--hs-border-subtle); border-radius: 6px; overflow: hidden; align-items: center; }
.hs-segment button {
  border: 0;
  background: var(--hs-surface-1);
  padding: 6px 14px;
  font-size: 13px;
  cursor: pointer;
}
.hs-segment button[aria-pressed='true'] { background: var(--hs-accent); color: #fff; }
.hs-horn-caption { font-size: 11px; color: var(--hs-text-secondary); padding: 0 10px; }

.hs-zoom { display: inline-flex; align-items: center; gap: 6px; }
.hs-zoom button { width: 28px; height: 28px; font-size: 14px; cursor: pointer; }
.hs-zoom-value { font-size: 13px; min-width: 44px; }

/* Transport bar (mirrors UI-004 surface). */
.transport-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  background: var(--hs-surface-1);
  border: 1px solid var(--hs-border-subtle);
  border-radius: 6px;
  padding: 8px 10px;
  margin: 10px 16px 0;
}
.transport-bar button { font-size: 13px; padding: 5px 10px; cursor: pointer; }
.transport-bar button.primary { border-color: var(--hs-accent); }
.transport-bar button.toggled,
.transport-bar button[aria-pressed='true'] { background: #d9e7d9; border-color: var(--hs-loop); }
.transport-bar button:disabled { opacity: 0.45; cursor: default; }
.resume-follow { border-color: var(--hs-active) !important; color: var(--hs-active); }
.time-readout { font-variant-numeric: tabular-nums; font-size: 15px; min-width: 170px; }
.rate, .check { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--hs-text-secondary); }

.waveform-area {
  background: var(--hs-surface-1);
  border: 1px solid var(--hs-border-subtle);
  border-radius: 6px;
  overflow: hidden;
  margin: 10px 16px 0;
}
.waveform { width: 100%; }
.timeline { border-top: 1px solid var(--hs-border-subtle); }

.hint { color: var(--hs-text-secondary); font-size: 12px; margin: 4px 16px 0; }

.hs-statusbar {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  padding: 6px 16px;
  font-size: 12px;
  color: var(--hs-text-secondary);
  font-variant-numeric: tabular-nums;
}

.hs-main {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 12px;
  padding: 10px 16px 16px;
  flex: 1;
  min-height: 0;
  align-items: start;
}

.hs-panel-title { font-size: 13px; margin: 0 0 8px; }

.hs-score-area {
  background: var(--hs-surface-1);
  border: 1px solid var(--hs-border-subtle);
  border-radius: 8px;
  min-height: 420px;
  display: flex;
  flex-direction: column;
}
.hs-score-scroll { overflow: auto; max-height: 62vh; padding: 16px; }
.hs-score-page {
  background: var(--hs-score-paper);
  margin: 0 auto 16px;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.12);
  width: fit-content;
}
/* Only the outer page svg is fluid-scaled — the nested svg.definition-scale
   carries the content viewBox and must not be restyled (UI-003 finding). */
.hs-score-page > svg { display: block; max-width: 100%; height: auto; }

/* Highlighting = pure class toggles; no re-render (UI-003 measurement). */
.hs-score-pages g.hs-selected :is(use, path, rect, ellipse, polygon):not(.hs-hit) {
  fill: var(--hs-accent);
  stroke: var(--hs-accent);
}
.hs-score-pages g.hs-active :is(use, path, rect, ellipse, polygon):not(.hs-hit) {
  fill: var(--hs-active);
  stroke: var(--hs-active);
}
.hs-score-pages g.hs-selected.hs-active :is(use, path, rect, ellipse, polygon):not(.hs-hit) {
  fill: var(--hs-accent-hover);
  stroke: var(--hs-accent-hover);
}
/* Loop passage indication: outline-style mark on overlapped notes. */
.hs-score-pages g.hs-loop :is(use, path, rect, ellipse, polygon):not(.hs-hit) {
  stroke: var(--hs-loop);
  stroke-width: 1.4;
}
.hs-score-pages g.hs-loop .notehead use { fill: var(--hs-loop); }
/* Current-measure wash: subtle background under the active measure group. */
.hs-score-pages g.hs-measure-active {
  fill: none;
}
.hs-score-pages g.hs-measure-active > rect.hs-measure-wash {
  fill: rgb(180 83 9 / 0.06);
}
.hs-score-pages g[id^='hs-'] { cursor: pointer; }

/* Invisible per-note hit area (domScore.ts): hollow noteheads are transparent
   in the middle, so glyph paint alone is not a reliable target. */
.hs-score-pages ellipse.hs-hit {
  fill: transparent;
  stroke: none;
  pointer-events: all;
}

.hs-error-panel { padding: 24px; }
.hs-error-panel h2 { font-size: 15px; margin: 0 0 8px; }
.hs-error-panel button { padding: 6px 16px; font-size: 13px; cursor: pointer; }
.hs-loading { padding: 24px; color: var(--hs-text-secondary); }

.follow-note {
  color: var(--hs-active);
  font-size: 12px;
  margin: 4px 16px 8px;
}
.follow-note .resume-follow { margin-left: 8px; }

.hs-side { display: flex; flex-direction: column; gap: 12px; }
.hs-side section {
  background: var(--hs-surface-1);
  border: 1px solid var(--hs-border-subtle);
  border-radius: 8px;
  padding: 12px;
}
.hs-props { margin: 0; font-size: 12px; display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; }
.hs-props dt { color: var(--hs-text-secondary); }
.hs-props dd { margin: 0; }
.hs-dim { color: var(--hs-text-secondary); font-size: 12px; }

.measure-panel { font-size: 12px; }
.measure-actions { display: flex; align-items: center; gap: 8px; margin: 8px 0; }
.measure-actions .stage { color: var(--hs-text-secondary); font-size: 12px; }
.measure-table { border-collapse: collapse; width: 100%; font-size: 11.5px; }
.measure-table th, .measure-table td {
  border: 1px solid var(--hs-border-subtle);
  padding: 4px 7px;
  text-align: left;
  vertical-align: top;
}
.measure-table th { color: var(--hs-text-secondary); font-weight: 600; }

.hs-footer {
  margin-top: auto;
  padding: 8px 16px;
  color: var(--hs-text-secondary);
  font-size: 12px;
  display: flex;
  gap: 16px;
}

:focus-visible { outline: 2px solid var(--hs-accent); outline-offset: 1px; }

@media (max-width: 1100px) {
  .hs-main { grid-template-columns: 1fr; }
}

/**
 * Minimal exact rational number for the sync layer.
 *
 * The Python engine (python/hornscribe/rhythm/timewarp.py, beatmap.py) keeps
 * all score positions as exact `fractions.Fraction` quarterLength values and
 * only treats seconds as floats. This module mirrors that contract so the
 * TypeScript port never accumulates binary floating-point drift in musical
 * positions: `Fraction(float)` semantics are reproduced by
 * {@link Rational.fromFloat}, which decomposes the IEEE-754 double exactly.
 *
 * Only the operations the TimeWarp/BeatMap slice needs are implemented.
 */
export class Rational {
  /** Normalized numerator (sign lives here). */
  readonly num: bigint
  /** Normalized denominator, always > 0. */
  readonly den: bigint

  private constructor(num: bigint, den: bigint) {
    if (den === 0n) throw new Error('Rational: denominator must not be 0')
    if (den < 0n) {
      num = -num
      den = -den
    }
    const g = gcd(abs(num), den)
    this.num = num / g
    this.den = den / g
  }

  static of(num: bigint | number, den: bigint | number = 1n): Rational {
    return new Rational(BigInt(num), BigInt(den))
  }

  static zero(): Rational {
    return new Rational(0n, 1n)
  }

  /**
   * Exact conversion of a finite IEEE-754 double — the equivalent of
   * Python's `Fraction(float_value)`. Rejects NaN/Infinity like
   * `Fraction()` does (ValueError/OverflowError there, Error here).
   */
  static fromFloat(value: number): Rational {
    if (!Number.isFinite(value)) {
      throw new Error(`Rational.fromFloat: value must be finite, got ${value}`)
    }
    if (value === 0) return Rational.zero()
    const buf = new DataView(new ArrayBuffer(8))
    buf.setFloat64(0, value)
    const bits = buf.getBigUint64(0)
    const sign = (bits >> 63n) === 1n ? -1n : 1n
    const expField = Number((bits >> 52n) & 0x7ffn)
    const mantissaField = bits & ((1n << 52n) - 1n)
    let num: bigint
    let e2: number
    if (expField === 0) {
      // subnormal
      num = mantissaField
      e2 = -1074
    } else {
      num = mantissaField | (1n << 52n)
      e2 = expField - 1075
    }
    num *= sign
    if (e2 >= 0) {
      return new Rational(num << BigInt(e2), 1n)
    }
    return new Rational(num, 1n << BigInt(-e2))
  }

  /** True when the value is a safe integer (cheap common path). */
  static from(value: number | bigint | Rational): Rational {
    if (value instanceof Rational) return value
    if (typeof value === 'bigint') return Rational.of(value)
    if (Number.isInteger(value) && Number.isSafeInteger(value)) {
      return Rational.of(value)
    }
    return Rational.fromFloat(value)
  }

  add(o: Rational): Rational {
    return new Rational(this.num * o.den + o.num * this.den, this.den * o.den)
  }

  sub(o: Rational): Rational {
    return new Rational(this.num * o.den - o.num * this.den, this.den * o.den)
  }

  mul(o: Rational): Rational {
    return new Rational(this.num * o.num, this.den * o.den)
  }

  div(o: Rational): Rational {
    if (o.num === 0n) throw new Error('Rational: division by zero')
    return new Rational(this.num * o.den, this.den * o.num)
  }

  neg(): Rational {
    return new Rational(-this.num, this.den)
  }

  cmp(o: Rational): number {
    const d = this.num * o.den - o.num * this.den
    return d < 0n ? -1 : d > 0n ? 1 : 0
  }

  lt(o: Rational): boolean {
    return this.cmp(o) < 0
  }
  le(o: Rational): boolean {
    return this.cmp(o) <= 0
  }
  gt(o: Rational): boolean {
    return this.cmp(o) > 0
  }
  ge(o: Rational): boolean {
    return this.cmp(o) >= 0
  }
  eq(o: Rational): boolean {
    return this.num === o.num && this.den === o.den
  }

  /** float(self) — nearest double; fine for seconds/DOM geometry. */
  toNumber(): number {
    return Number(this.num) / Number(this.den)
  }

  toString(): string {
    return this.den === 1n ? `${this.num}` : `${this.num}/${this.den}`
  }
}

function abs(v: bigint): bigint {
  return v < 0n ? -v : v
}

function gcd(a: bigint, b: bigint): bigint {
  let x = a
  let y = b
  while (y !== 0n) {
    const t = y
    y = x % y
    x = t
  }
  return x === 0n ? 1n : x
}

// @vitest-environment jsdom
import { describe, expect, it } from 'vitest'
import concertXml from '../../fixtures/sync_concert.musicxml?raw'
import { Rational } from './rational'
import { ScoreSyncEngine, sameSet } from './syncEngine'
import { buildSyncMap } from './syncMap'
import { TimeWarp } from './timewarp'

const map = buildSyncMap(concertXml)
const warp = TimeWarp.fixedBpm(100, 0) // 100 bpm → 0.6 s per ql

function engine() {
  return new ScoreSyncEngine(map, warp)
}

function ids(s: ReadonlySet<string>): string[] {
  return [...s].sort()
}

describe('ScoreSyncEngine.activeAt (ql → canonical set)', () => {
  const e = engine()

  it('activates on note onsets, not before', () => {
    expect(ids(e.activeAtQl(Rational.of(0)))).toEqual(['sn-000001'])
    expect(ids(e.activeAtQl(Rational.of(1)))).toEqual(['sn-000002'])
    expect(e.activeAtQl(Rational.of(-1)).size).toBe(0)
  })

  it('a note stays active through its duration (half-open [onset,offset))', () => {
    // sn-000002 is an eighth spanning ql 1–1.5: active at 1.4;
    // sn-000003 takes over at 1.5, sn-000004 at 2.
    expect(ids(e.activeAtQl(Rational.of(14, 10)))).toEqual(['sn-000002'])
    expect(ids(e.activeAtQl(Rational.of(19, 10)))).toEqual(['sn-000003'])
    expect(ids(e.activeAtQl(Rational.of(2)))).toEqual(['sn-000004'])
  })

  it('a tied note is active as ONE canonical id across all fragments', () => {
    // sn-000012 spans 10–14 (fragments in m3 and m4).
    expect(ids(e.activeAtQl(Rational.of(10)))).toEqual(['sn-000012'])
    expect(ids(e.activeAtQl(Rational.of(13)))).toEqual(['sn-000012']) // fragment 2
    // sn-000038 spans 42–45.5 across m11/m12 (3 fragments).
    expect(ids(e.activeAtQl(Rational.of(451, 10)))).toEqual(['sn-000038'])
  })

  it('returns empty in true gaps (rests, unwritten space, piece end)', () => {
    expect(e.activeAtQl(Rational.of(15)).size).toBe(0) // m4 half rest
    expect(e.activeAtQl(Rational.of(63, 2)).size).toBe(0) // m8 eighth rest
    expect(e.activeAtQl(Rational.of(48)).size).toBe(0) // end of piece
  })
})

describe('ScoreSyncEngine.nearestCanonicalAtSeconds (waveform-click context)', () => {
  const e = engine()

  it('returns the sounding note when inside one', () => {
    expect(e.nearestCanonicalAtSeconds(0.3)?.canonicalId).toBe('sn-000001') // ql 0.5
    expect(e.nearestCanonicalAtSeconds(13 * 0.6)?.canonicalId).toBe('sn-000012')
  })

  it('resolves rest gaps to the boundary-nearest note', () => {
    // rest 14–16 between sn-000012 (offset 14) and sn-000014 (onset 16):
    // midpoint ql 15 → tie → earlier span wins (deterministic scan order).
    expect(e.nearestCanonicalAtSeconds(15 * 0.6)?.canonicalId).toBe('sn-000012')
    expect(e.nearestCanonicalAtSeconds(15.4 * 0.6)?.canonicalId).toBe('sn-000014')
    // m8 rest 31–32: ql 31.5 → tie → earlier span sn-000027.
    expect(e.nearestCanonicalAtSeconds(31.5 * 0.6)?.canonicalId).toBe('sn-000027')
  })
})

describe('ScoreSyncEngine.loop → score context', () => {
  const e = engine()

  it('canonicalsInRange uses half-open overlap [start,end)', () => {
    // loop over m3 (ql 8–12): sn-000010(8–9), sn-000011(9–10),
    // sn-000012(10–14), sn-000013(11.5–12.5) all overlap;
    // sn-000009 (6–8) only touches → excluded.
    // NOTE: bounds sit exactly on ql 8/12 *by construction* here — use
    // qlDomainInRange to avoid seconds→ql double noise (see next test).
    const got = e.canonicalIdsInRange(Rational.of(8), Rational.of(12))
    expect(ids(got)).toEqual(['sn-000010', 'sn-000011', 'sn-000012', 'sn-000013'])
  })

  it('canonicalsInRange (seconds) carries float noise at exact boundaries', () => {
    // 8*0.6 as a double maps to ql 7.9999999999999997 — just below the
    // boundary — so the touch-only neighbour sn-000009 legitimately overlaps.
    // This documents the seconds-domain edge; interior bounds are stable.
    const boundary = e.canonicalsInRange({ start: 8 * 0.6, end: 12 * 0.6 })
    expect(boundary.has('sn-000009')).toBe(true) // float noise, documented
    const interior = e.canonicalsInRange({ start: 8.4 * 0.6, end: 11.9 * 0.6 })
    expect(ids(interior)).toEqual([
      'sn-000010',
      'sn-000011',
      'sn-000012',
      'sn-000013',
    ])
  })

  it('measuresInRange covers measures overlapped by the loop', () => {
    const nums = e
      .measuresInRange({ start: 10 * 0.6, end: 13 * 0.6 })
      .map((m) => m.number)
    expect(nums).toEqual([3, 4]) // 10–13 overlaps m3 (8–12) and m4 (12–16)
    // Exact ql-domain bounds: loop [8,12) touches m2 (ends at 8) and m4
    // (starts at 12) without overlapping → only m3.
    expect(
      e.measuresInQlRange(Rational.of(8), Rational.of(12)).map((m) => m.number),
    ).toEqual([3])
  })
})

describe('ScoreSyncEngine seconds bridge', () => {
  const e = engine()

  it('secondsForCanonical = qlToSeconds(onset) — score-click seek target', () => {
    expect(e.secondsForCanonical('sn-000005')).toBeCloseTo(3 * 0.6, 10)
    expect(e.secondsForCanonical('sn-000040')).toBeCloseTo(46 * 0.6, 10)
    expect(e.secondsForCanonical('nope')).toBeNull()
  })

  it('secondsRangeForCanonical spans the full tied duration', () => {
    const r = e.secondsRangeForCanonical('sn-000012')!
    expect(r.start).toBeCloseTo(10 * 0.6, 10)
    expect(r.end).toBeCloseTo(14 * 0.6, 10)
  })

  it('measureAtSeconds + scoreEndSeconds', () => {
    expect(e.measureAtSeconds(15 * 0.6)?.number).toBe(4) // inside m4 rest
    expect(e.scoreEndSeconds()).toBeCloseTo(48 * 0.6, 10)
  })

  it('sameSet drives cheap highlight diffs', () => {
    expect(sameSet(new Set(['a', 'b']), new Set(['b', 'a']))).toBe(true)
    expect(sameSet(new Set(['a']), new Set(['a', 'b']))).toBe(false)
  })
})

/**
 * ScoreSyncEngine — the headless heart of UI-005.
 *
 * Owns the canonical chain for one loaded (score, warp) pair:
 *
 *   audio seconds ──warp.secondsToQl──▶ ql ──syncMap──▶ canonical ids
 *   canonical id  ──onsetQl──▶ ql ──warp.qlToSeconds──▶ audio seconds
 *
 * Everything here is DOM-free and deterministic: React components and the
 * measurement harness call the same methods, and the unit tests exercise
 * this class without any renderer (no Verovio, no wavesurfer).
 *
 * Span semantics: a canonical note is "active" on the half-open interval
 * [onsetQl, offsetQl) — the same half-open convention as the transport loop.
 */
import { Rational } from './rational'
import type { CanonicalSpan, MeasureSpan, SyncMap } from './syncMap'
import type { TimeWarp } from './timewarp'

export interface TimeRangeSec {
  start: number
  end: number
}

export class ScoreSyncEngine {
  private readonly byCanonical = new Map<string, CanonicalSpan>()
  /** Spans sorted by onset for binary search. */
  private readonly spans: CanonicalSpan[]

  constructor(
    readonly map: SyncMap,
    readonly warp: TimeWarp,
  ) {
    this.spans = [...map.spans].sort((a, b) => a.onsetQl.cmp(b.onsetQl))
    for (const s of this.spans) this.byCanonical.set(s.canonicalId, s)
  }

  /** All canonical ids known to the map. */
  canonicalIds(): string[] {
    return [...this.byCanonical.keys()]
  }

  span(canonicalId: string): CanonicalSpan | null {
    return this.byCanonical.get(canonicalId) ?? null
  }

  // ---- seconds -> score ---------------------------------------------------

  /** Exact score position for an audio-clock time. */
  qlAtSeconds(timeSec: number): Rational {
    return this.warp.secondsToQl(timeSec)
  }

  /** Canonical notes sounding at `timeSec` ([onset, offset) semantics). */
  activeAtSeconds(timeSec: number): Set<string> {
    return this.activeAtQl(this.qlAtSeconds(timeSec))
  }

  activeAtQl(q: Rational): Set<string> {
    const out = new Set<string>()
    for (const s of this.spans) {
      if (s.onsetQl.gt(q)) break // spans sorted by onset
      if (s.onsetQl.le(q) && s.offsetQl.gt(q)) out.add(s.canonicalId)
    }
    return out
  }

  /**
   * Nearest meaningful canonical element for an arbitrary audio time
   * (waveform click): a note sounding at `t` wins; otherwise the span whose
   * onset or offset boundary is closest. Returns null only for empty maps.
   */
  nearestCanonicalAtSeconds(timeSec: number): CanonicalSpan | null {
    const q = this.qlAtSeconds(timeSec)
    const active = this.activeAtQl(q)
    if (active.size > 0) {
      // Multiple actives only occur with overlaps (chords/voices); pick the
      // earliest onset for determinism.
      let best: CanonicalSpan | null = null
      for (const s of this.spans) {
        if (active.has(s.canonicalId)) {
          best = s
          break
        }
      }
      return best
    }
    let best: CanonicalSpan | null = null
    let bestDist: Rational | null = null
    for (const s of this.spans) {
      const d = q.lt(s.onsetQl) ? s.onsetQl.sub(q) : q.sub(s.offsetQl)
      if (bestDist === null || d.lt(bestDist)) {
        bestDist = d
        best = s
      }
    }
    return best
  }

  // ---- score -> seconds ---------------------------------------------------

  /** Audio-clock onset of a canonical note (score click -> seek target). */
  secondsForCanonical(canonicalId: string): number | null {
    const s = this.byCanonical.get(canonicalId)
    return s ? this.warp.qlToSeconds(s.onsetQl) : null
  }

  /** Audio-clock [start,end) span of a canonical note (sounding span). */
  secondsRangeForCanonical(canonicalId: string): TimeRangeSec | null {
    const s = this.byCanonical.get(canonicalId)
    if (!s) return null
    return {
      start: this.warp.qlToSeconds(s.onsetQl),
      end: this.warp.qlToSeconds(s.offsetQl),
    }
  }

  // ---- loop <-> score passage ----------------------------------------------

  /**
   * Canonical notes whose sounding span intersects a half-open audio range
   * [start,end) — the score-side view of an armed A-B loop.
   */
  canonicalsInRange(range: TimeRangeSec): Set<string> {
    return this.canonicalIdsInRange(
      this.warp.secondsToQl(range.start),
      this.warp.secondsToQl(range.end),
    )
  }

  /**
   * Same overlap test on exact ql bounds — preferable when the caller already
   * holds score-domain positions, because seconds→ql conversion can land an
   * interval hairline-inside a neighbouring span (documented in tests).
   */
  canonicalIdsInRange(startQl: Rational, endQl: Rational): Set<string> {
    const out = new Set<string>()
    for (const s of this.spans) {
      // overlap of [s.onset, s.offset) with [startQl, endQl)
      if (s.offsetQl.gt(startQl) && s.onsetQl.lt(endQl)) out.add(s.canonicalId)
      if (s.onsetQl.ge(endQl)) break
    }
    return out
  }

  /** Measure numbers intersecting an audio range (for the loop label). */
  measuresInRange(range: TimeRangeSec): MeasureSpan[] {
    return this.measuresInQlRange(
      this.warp.secondsToQl(range.start),
      this.warp.secondsToQl(range.end),
    )
  }

  /** Exact-ql variant of {@link measuresInRange}. */
  measuresInQlRange(startQl: Rational, endQl: Rational): MeasureSpan[] {
    return this.map.measures.filter(
      (m) => m.endQl.gt(startQl) && m.startQl.lt(endQl),
    )
  }

  /** Measure containing an audio time (current-measure readout). */
  measureAtSeconds(timeSec: number): MeasureSpan | null {
    const q = this.qlAtSeconds(timeSec)
    for (const m of this.map.measures) {
      if (m.startQl.le(q) && m.endQl.gt(q)) return m
    }
    return null
  }

  /** End of the notated score in audio seconds (transport clamp context). */
  scoreEndSeconds(): number {
    return this.warp.qlToSeconds(this.map.durationQl)
  }
}

/** Set equality helper for highlight-diff bookkeeping. */
export function sameSet(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false
  for (const v of a) if (!b.has(v)) return false
  return true
}

