/**
 * Canonical sync map: MusicXML -> ordered canonical note spans in exact
 * quarterLength (ql) positions.
 *
 * This is the middle of the canonical chain (MASTER_PLAN §9):
 *
 *   audio seconds ↔ TimeWarp ↔ canonical note ids ↔ MusicXML @id ↔ rendered elements
 *
 * Positions are computed from MusicXML `<duration>`/`<divisions>` only —
 * deterministic, independent of the renderer. Verovio's timemap is used by
 * the spike app only as a cross-check (see syncMap.verovio.test.ts); the
 * product chain never routes sync through renderer internals.
 *
 * Element-level rules mirrored from the Python engine (domain/ids.py):
 *  - `hs-sn-<6 digits>(-<k>)` export ids resolve to canonical `sn-*`;
 *    consecutive <note> elements sharing one canonical id are tie fragments
 *    of the same canonical note (fragment 1 carries the onset).
 *  - `hs-rest-*` carries no canonical identity but still advances the cursor.
 *  - `<chord/>` notes share the previous onset; `<backup>`/`<forward>` move
 *    the cursor (multi-voice safety), and `<divisions>` may change per
 *    measure attributes.
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlRestId } from '../score/ids'
import { Rational } from './rational'

/** One canonical note's sounding span (merged across tie fragments). */
export interface CanonicalSpan {
  /** Canonical score note id (`sn-000003`). */
  canonicalId: string
  /** Ordered MusicXML export ids of its fragments (`hs-sn-000003`, `-2`, …). */
  exportIds: string[]
  /** Exact onset position in ql. */
  onsetQl: Rational
  /** Exact offset (end of the last fragment) in ql. */
  offsetQl: Rational
  /** 1-based measure number where the first fragment starts. */
  measure: number
}

/** Measure boundaries in ql (for loop-passage indication and labels). */
export interface MeasureSpan {
  /** Measure `number` attribute (1-based in the fixtures). */
  number: number
  startQl: Rational
  endQl: Rational
}

export interface SyncMap {
  /** Canonical spans sorted by onset. */
  spans: CanonicalSpan[]
  /** Measure spans sorted by startQl. */
  measures: MeasureSpan[]
  /** Total notated length in ql (last offset / measure end). */
  durationQl: Rational
}

interface RawNote {
  exportId: string
  canonicalId: string | null
  isRest: boolean
  chord: boolean
  onsetQl: Rational
  offsetQl: Rational
  measure: number
}

/**
 * Parse a score-partwise MusicXML string into a {@link SyncMap}.
 * Single-part documents are the spike scope (same as ENG-001 fixtures).
 * Throws on unparsable XML so callers can surface the copy-deck error state.
 */
export function buildSyncMap(xml: string): SyncMap {
  const doc = new DOMParser().parseFromString(xml, 'application/xml')
  if (doc.querySelector('parsererror')) {
    throw new Error('MusicXML parse failed')
  }
  const spans: CanonicalSpan[] = []
  const measures: MeasureSpan[] = []
  let lastOffset = Rational.zero()

  for (const part of Array.from(doc.querySelectorAll('score-partwise > part'))) {
    let cursor = Rational.zero()
    let prev: RawNote | null = null
    /** Canonical id -> span accumulator. Fragments of one canonical note are
     *  merged by id, NOT by adjacency: a foreign note (e.g. sn-000013 between
     *  hs-sn-000012 and hs-sn-000012-2 across a barline) may sit between two
     *  fragments of the same tied note in document order. */
    const spanByCanonical = new Map<string, CanonicalSpan>()
    /** <divisions> persists until redefined (MusicXML semantics) — it must
     *  NOT reset per measure. */
    let divisions = Rational.of(1)

    for (const measure of Array.from(part.querySelectorAll(':scope > measure'))) {
      const measureStart = cursor
      const number = Number(measure.getAttribute('number') ?? measures.length + 1)
      // In MusicXML, <backup>/<forward> move the cursor inside a measure;
      // a measure's extent is the max cursor reached, not the final cursor.
      let measureEnd = cursor

      for (const el of Array.from(measure.children)) {
        const tag = el.tagName
        if (tag === 'attributes') {
          const div = el.querySelector(':scope > divisions')?.textContent
          if (div !== null && div !== undefined) {
            const d = Number(div)
            if (Number.isFinite(d) && d > 0) divisions = Rational.of(Math.round(d))
          }
        } else if (tag === 'note') {
          const durEl = el.querySelector(':scope > duration')?.textContent
          const durTicks = durEl ? Number(durEl) : 0
          const durQl = Number.isFinite(durTicks)
            ? Rational.of(Math.round(durTicks)).div(divisions)
            : Rational.zero()
          const chord = el.querySelector(':scope > chord') !== null
          const onset = chord && prev ? prev.onsetQl : cursor
          const offset = onset.add(durQl)
          const exportId = el.getAttribute('id') ?? ''
          const canonicalId = canonicalNoteIdFromMusicxml(exportId)
          const raw: RawNote = {
            exportId,
            canonicalId,
            isRest:
              el.querySelector(':scope > rest') !== null || isMusicxmlRestId(exportId),
            chord,
            onsetQl: onset,
            offsetQl: offset,
            measure: number,
          }
          if (!chord) cursor = cursor.add(durQl)
          measureEnd = measureEnd.gt(cursor) ? measureEnd : cursor
          prev = raw

          if (canonicalId !== null) {
            // Merge every fragment of the same canonical note into one span.
            const existing = spanByCanonical.get(canonicalId)
            if (existing) {
              existing.exportIds.push(exportId)
              if (offset.gt(existing.offsetQl)) existing.offsetQl = offset
              if (onset.lt(existing.onsetQl)) existing.onsetQl = onset
            } else {
              spanByCanonical.set(canonicalId, {
                canonicalId,
                exportIds: [exportId],
                onsetQl: onset,
                offsetQl: offset,
                measure: number,
              })
            }
          }
        } else if (tag === 'backup' || tag === 'forward') {
          const durEl = el.querySelector(':scope > duration')?.textContent
          const durTicks = durEl ? Number(durEl) : 0
          if (Number.isFinite(durTicks)) {
            const delta = Rational.of(Math.round(durTicks)).div(divisions)
            cursor = tag === 'backup' ? cursor.sub(delta) : cursor.add(delta)
            if (cursor.lt(Rational.zero())) cursor = Rational.zero()
            measureEnd = measureEnd.gt(cursor) ? measureEnd : cursor
          }
          prev = null
        } else {
          // direction/sound/print etc. — inert for the map.
        }
      }

      if (measureEnd.gt(measureStart)) {
        measures.push({ number, startQl: measureStart, endQl: measureEnd })
        cursor = measureEnd
      }
      lastOffset = lastOffset.gt(cursor) ? lastOffset : cursor
      prev = null
    }
    for (const s of spanByCanonical.values()) spans.push(s)
  }

  spans.sort((a, b) => a.onsetQl.cmp(b.onsetQl))
  return { spans, measures, durationQl: lastOffset }
}

/**
 * Convenience: pitch (midi) per canonical id, derived from the first
 * fragment's <pitch> — used by the audio synth so fixture tones match the
 * concert-pitch score. Returns null for non-pitched elements.
 */
export function pitchMidiByCanonical(
  xml: string,
): Map<string, { midi: number; span: CanonicalSpan }> {
  const doc = new DOMParser().parseFromString(xml, 'application/xml')
  const map = buildSyncMap(xml)
  const byExport = new Map<string, CanonicalSpan>()
  for (const s of map.spans) for (const id of s.exportIds) byExport.set(id, s)
  const out = new Map<string, { midi: number; span: CanonicalSpan }>()
  for (const noteEl of Array.from(doc.querySelectorAll('part > measure > note'))) {
    const exportId = noteEl.getAttribute('id') ?? ''
    const canonicalId = canonicalNoteIdFromMusicxml(exportId)
    if (!canonicalId || out.has(canonicalId)) continue
    const step = noteEl.querySelector('pitch > step')?.textContent
    const octave = Number(noteEl.querySelector('pitch > octave')?.textContent)
    const alter = Number(noteEl.querySelector('pitch > alter')?.textContent ?? 0)
    const span = byExport.get(exportId)
    if (!step || !Number.isFinite(octave) || !span) continue
    const base = STEP_SEMITONE[step]
    if (base === undefined) continue
    const midi = (octave + 1) * 12 + base + (Number.isFinite(alter) ? alter : 0)
    out.set(canonicalId, { midi, span })
  }
  return out
}

const STEP_SEMITONE: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
}

// @vitest-environment jsdom
import { describe, expect, it, beforeAll } from 'vitest'
import concertXml from '../../fixtures/sync_concert.musicxml?raw'
import { Rational } from './rational'
import { buildSyncMap } from './syncMap'
import { getScoreRenderer, type ScoreRenderer } from '../score/verovio'

/**
 * Cross-validation: the spike's own MusicXML→ql map (syncMap — the same
 * contract as rhythm/timemap.py build_timemap) must agree with the *rendered
 * view's own clock* (Verovio's timemap / getTimeForElement) for every note.
 * If they agree, either side of the chain can drive the other: the engine
 * uses the exact-ql side, Verovio stays the visual renderer.
 *
 * Verovio reports element times in milliseconds at the document tempo
 * (100 bpm ⇒ 600 ms per ql).
 */

const MS_PER_QL = 600

let renderer: ScoreRenderer

beforeAll(async () => {
  renderer = await getScoreRenderer()
  renderer.load(concertXml)
})

describe('Verovio timemap vs syncMap (rendered-view clock agreement)', () => {
  const map = buildSyncMap(concertXml)

  it('every fragment onset matches getTimeForElement within 1 ms', () => {
    let checked = 0
    for (const span of map.spans) {
      for (const [i, id] of span.exportIds.entries()) {
        const ms = renderer.timeForElement(id)
        // Fragment 1 onset == span onset; continuation fragments are checked
        // through getElementsAtTime below (their ql onsets aren't in the span).
        if (i === 0) {
          const expected = span.onsetQl.toNumber() * MS_PER_QL
          expect(ms, `${id} not found`).not.toBeNull()
          expect(Math.abs(ms! - expected), `${id}`).toBeLessThanOrEqual(1)
        } else {
          expect(ms, `fragment ${id} must exist in Verovio's clock`).not.toBeNull()
        }
        checked++
      }
    }
    expect(checked).toBe(44) // 40 canonical notes + 4 continuation fragments
  })

  it('getElementsAtTime reports our canonical ids at their onsets', () => {
    const t = renderer.elementsAtTime(3 * MS_PER_QL) // ql 3 → sn-000005
    expect(t?.notes).toContain('hs-sn-000005')
    const t2 = renderer.elementsAtTime(10 * MS_PER_QL)
    expect(t2?.notes).toContain('hs-sn-000012') // tie head at ql 10
    // Inside the tie continuation (ql 13, still sounding) Verovio reports the
    // continuation fragment belonging to canonical sn-000012.
    const t3 = renderer.elementsAtTime(13 * MS_PER_QL)
    expect(t3?.notes.some((id) => id.startsWith('hs-sn-000012'))).toBe(true)
  })

  it('timemap duration covers the piece (last offset ≈ 48 ql)', () => {
    const last = map.spans[map.spans.length - 1]
    expect(last.onsetQl.eq(Rational.of(46))).toBe(true)
    expect(renderer.durationMs()).toBeGreaterThanOrEqual(48 * MS_PER_QL - 1)
  })
})

import { describe, expect, it } from 'vitest'
import { Rational } from './rational'
import { TimeWarp } from './timewarp'

/**
 * Mirrors of the Python contract (rhythm/timewarp.py): fixed_bpm linear map,
 * piecewise-linear beat-map warp, nearest-segment extrapolation, validation.
 */

describe('Rational', () => {
  it('normalizes and compares exactly', () => {
    expect(Rational.of(2, 4).eq(Rational.of(1, 2))).toBe(true)
    expect(Rational.of(1, 3).add(Rational.of(1, 6)).eq(Rational.of(1, 2))).toBe(true)
    expect(Rational.of(1, 10).add(Rational.of(2, 10)).toString()).toBe('3/10')
  })

  it('fromFloat is exact (Fraction(float) equivalent)', () => {
    // 0.1 is not exact in binary; the Rational must hold the true double value.
    const r = Rational.fromFloat(0.1)
    expect(r.toNumber()).toBe(0.1)
    // 0.1 + 0.2 in rationals must exceed the double 0.3 (classic check).
    const sum = Rational.fromFloat(0.1).add(Rational.fromFloat(0.2))
    expect(sum.eq(Rational.fromFloat(0.3))).toBe(false)
    expect(sum.gt(Rational.fromFloat(0.3))).toBe(true)
  })

  it('rejects non-finite values', () => {
    expect(() => Rational.fromFloat(NaN)).toThrow()
    expect(() => Rational.fromFloat(Infinity)).toThrow()
    expect(() => Rational.of(1, 0)).toThrow()
  })
})

describe('TimeWarp.fixedBpm', () => {
  it('maps seconds to ql linearly (design 6.2)', () => {
    const w = TimeWarp.fixedBpm(120, 0) // 2 ql per second
    expect(w.secondsToQl(1).eq(Rational.of(2))).toBe(true)
    expect(w.secondsToQl(0.5).eq(Rational.of(1))).toBe(true)
    expect(w.qlToSeconds(Rational.of(4))).toBe(2)
  })

  it('honours zero_sec offset', () => {
    const w = TimeWarp.fixedBpm(100, 0.4)
    // ql = (t - 0.4) * 100/60 ; t=0.4 -> 0 exactly (same double).
    expect(w.secondsToQl(0.4).eq(Rational.of(0))).toBe(true)
    // t=1.0 -> (1.0-0.4) is the double 0.59999999999999998; the result is the
    // exact Fraction(double) product — compare as float like the Python side.
    expect(w.secondsToQl(1.0).toNumber()).toBeCloseTo(1.0, 12)
    expect(w.qlToSeconds(Rational.of(1))).toBeCloseTo(1.0, 10)
    expect(w.qlToSeconds(Rational.of(0))).toBeCloseTo(0.4, 10)
  })

  it('validates inputs like the Python factory', () => {
    expect(() => TimeWarp.fixedBpm(0)).toThrow()
    expect(() => TimeWarp.fixedBpm(-120)).toThrow()
    expect(() => TimeWarp.fixedBpm(120, NaN)).toThrow()
  })
})

describe('TimeWarp.fromAnchors', () => {
  const anchors = [
    { timeSec: 0.4, scorePosQl: Rational.of(0) },
    { timeSec: 2.4, scorePosQl: Rational.of(4) }, // 2 ql/s
    { timeSec: 6.4, scorePosQl: Rational.of(8) }, // 1 ql/s — ritardando
  ]

  it('passes exactly through every anchor', () => {
    const w = TimeWarp.fromAnchors(anchors)
    for (const a of anchors) {
      expect(w.secondsToQl(a.timeSec).eq(a.scorePosQl)).toBe(true)
      expect(w.qlToSeconds(a.scorePosQl)).toBeCloseTo(a.timeSec, 10)
    }
  })

  it('interpolates piecewise-linearly between anchors', () => {
    const w = TimeWarp.fromAnchors(anchors)
    // midpoint of segment 1: t=1.4 -> ql ≈ 2 (exact up to double repr of t)
    expect(w.secondsToQl(1.4).toNumber()).toBeCloseTo(2, 12)
    // midpoint of segment 2: t=4.4 -> ql ≈ 6
    expect(w.secondsToQl(4.4).toNumber()).toBeCloseTo(6, 12)
    expect(w.qlToSeconds(Rational.of(6))).toBeCloseTo(4.4, 10)
  })

  it('extrapolates with the nearest segment slope', () => {
    const w = TimeWarp.fromAnchors(anchors)
    // before first anchor: slope 2 ql/s -> t=0 -> ql ≈ -0.8
    expect(w.secondsToQl(0).toNumber()).toBeCloseTo(-0.8, 12)
    // after last anchor: slope 1 ql/s -> t=8.4 -> ql ≈ 10
    expect(w.secondsToQl(8.4).toNumber()).toBeCloseTo(10, 12)
    expect(w.qlToSeconds(Rational.of(10))).toBeCloseTo(8.4, 10)
  })

  it('rejects invalid beat maps (mirrors InvalidBeatMapError)', () => {
    expect(() => TimeWarp.fromAnchors([])).toThrow()
    expect(() => TimeWarp.fromAnchors([anchors[0]])).toThrow()
    expect(() =>
      TimeWarp.fromAnchors([
        { timeSec: 1, scorePosQl: Rational.of(0) },
        { timeSec: 1, scorePosQl: Rational.of(4) }, // duplicate time
      ]),
    ).toThrow(/strictly increase/)
    expect(() =>
      TimeWarp.fromAnchors([
        { timeSec: 0, scorePosQl: Rational.of(0) },
        { timeSec: 1, scorePosQl: Rational.of(4) },
        { timeSec: 2, scorePosQl: Rational.of(4) }, // non-monotonic position
      ]),
    ).toThrow(/monotonic/)
    expect(() =>
      TimeWarp.fromAnchors([
        { timeSec: NaN, scorePosQl: Rational.of(0) },
        { timeSec: 1, scorePosQl: Rational.of(4) },
      ]),
    ).toThrow()
  })

  it('sorts anchors by time (input order does not matter)', () => {
    const w = TimeWarp.fromAnchors([anchors[2], anchors[0], anchors[1]])
    expect(w.secondsToQl(2.4).eq(Rational.of(4))).toBe(true)
  })

  it('rejects a float position in qlToSeconds (Python contract)', () => {
    const w = TimeWarp.fromAnchors(anchors)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    expect(() => w.qlToSeconds(4 as any)).toThrow()
  })
})

/**
 * TypeScript mirror of the Python engine's time-warp contract
 * (`python/hornscribe/rhythm/timewarp.py` + `beatmap.py`,
 * QUANTIZER_DESIGN.md §5.2/§6). This is the seconds ↔ quarterLength (ql)
 * boundary of the canonical sync chain:
 *
 *   audio seconds  ↔  TimeWarp  ↔  score position (ql)  ↔  canonical note ids
 *
 * Ported semantics (kept identical to the Python contract):
 *  - `fixedBpm(bpm, zeroSec)`: linear map `ql = (t - zeroSec) * bpm / 60`.
 *  - `fromAnchors(anchors)`: piecewise-linear warp through beat anchors —
 *    passes exactly through every anchor, stays monotonic, never overshoots.
 *  - Out-of-range inputs extrapolate with the nearest segment slope.
 *  - Positions are exact {@link Rational} values; seconds are floats.
 *  - `qlToSeconds` requires an exact position input (Rational), mirroring the
 *    Python rule that floats are rejected there.
 *
 * BeatMap validation is mirrored: >= 2 anchors, times strictly increasing,
 * score positions strictly increasing (InvalidBeatMapError -> Error here).
 */
import { Rational } from './rational'

export interface BeatAnchor {
  /** Physical performance time in seconds (float, raw-evidence domain). */
  timeSec: number
  /** Exact score position in quarterLength units. */
  scorePosQl: Rational
}

export type TimeWarpMode = 'fixed_bpm' | 'beat_map'

export class TimeWarp {
  private constructor(
    readonly mode: TimeWarpMode,
    private readonly qlPerSec: Rational | null,
    private readonly zeroSec: Rational | null,
    private readonly times: readonly Rational[],
    private readonly positions: readonly Rational[],
    /** Float mirror of `times` for the fast segment search. */
    private readonly timesFloat: readonly number[],
  ) {}

  /** Linear warp `ql = (timeSec - zeroSec) * bpm / 60` (design 6.2). */
  static fixedBpm(bpm: number, zeroSec = 0): TimeWarp {
    if (!Number.isFinite(bpm) || bpm <= 0) {
      throw new Error(`bpm must be a positive finite number, got ${bpm}`)
    }
    if (!Number.isFinite(zeroSec)) {
      throw new Error(`zeroSec must be finite, got ${zeroSec}`)
    }
    return new TimeWarp(
      'fixed_bpm',
      Rational.fromFloat(bpm).div(Rational.of(60)),
      Rational.fromFloat(zeroSec),
      [],
      [],
      [],
    )
  }

  /**
   * Piecewise-linear warp through `anchors` (design 6.1). Between anchors
   * `(t0,q0)` and `(t1,q1)`: `W(t) = q0 + (t - t0)/(t1 - t0) * (q1 - q0)`,
   * computed in exact rational arithmetic after `Fraction(float)`-equivalent
   * conversion, so the warp passes through every anchor exactly.
   */
  static fromAnchors(anchors: readonly BeatAnchor[]): TimeWarp {
    const sorted = [...anchors].sort((a, b) => a.timeSec - b.timeSec)
    if (sorted.length < 2) {
      throw new Error(`beat map needs at least 2 anchors, got ${sorted.length}`)
    }
    for (const a of sorted) {
      if (!Number.isFinite(a.timeSec)) {
        throw new Error(`anchor timeSec must be finite, got ${a.timeSec}`)
      }
    }
    for (let i = 1; i < sorted.length; i += 1) {
      const prev = sorted[i - 1]
      const cur = sorted[i]
      if (cur.timeSec <= prev.timeSec) {
        throw new Error(
          `anchor times must strictly increase: ${prev.timeSec} !< ${cur.timeSec}`,
        )
      }
      if (cur.scorePosQl.le(prev.scorePosQl)) {
        throw new Error(
          `beat map must be monotonic: scorePosQl did not increase ` +
            `(${prev.scorePosQl} -> ${cur.scorePosQl} at ${cur.timeSec}s)`,
        )
      }
    }
    return new TimeWarp(
      'beat_map',
      null,
      null,
      sorted.map((a) => Rational.fromFloat(a.timeSec)),
      sorted.map((a) => a.scorePosQl),
      sorted.map((a) => a.timeSec),
    )
  }

  /** Tempo for fixed_bpm warps, else null. */
  get bpm(): number | null {
    return this.qlPerSec === null ? null : this.qlPerSec.mul(Rational.of(60)).toNumber()
  }

  /** Score-origin offset for fixed_bpm warps, else null. */
  get zeroSecValue(): number | null {
    return this.zeroSec === null ? null : this.zeroSec.toNumber()
  }

  /** Map a time in seconds to an exact quarterLength position. */
  secondsToQl(timeSec: number): Rational {
    if (!Number.isFinite(timeSec)) {
      throw new Error(`timeSec must be finite, got ${timeSec}`)
    }
    const t = Rational.fromFloat(timeSec)
    if (this.mode === 'fixed_bpm') {
      return t.sub(this.zeroSec!).mul(this.qlPerSec!)
    }
    const i = segmentIndex(this.times, this.timesFloat, t, timeSec)
    const t0 = this.times[i]
    const t1 = this.times[i + 1]
    const q0 = this.positions[i]
    const q1 = this.positions[i + 1]
    return q0.add(t.sub(t0).mul(q1.sub(q0)).div(t1.sub(t0)))
  }

  /** Convenience float view of {@link secondsToQl}. */
  secondsToQlNumber(timeSec: number): number {
    return this.secondsToQl(timeSec).toNumber()
  }

  /**
   * Inverse map: exact quarterLength position -> seconds (design 6.1).
   * The input must be a {@link Rational} — floats are rejected so drifted
   * positions cannot be mapped silently (same rule as the Python side).
   */
  qlToSeconds(posQl: Rational): number {
    if (!(posQl instanceof Rational)) {
      throw new Error('posQl must be an exact Rational')
    }
    if (this.mode === 'fixed_bpm') {
      return this.zeroSec!.add(posQl.div(this.qlPerSec!)).toNumber()
    }
    const i = segmentIndex(this.positions, null, posQl, posQl.toNumber())
    const q0 = this.positions[i]
    const q1 = this.positions[i + 1]
    const t0 = this.times[i]
    const t1 = this.times[i + 1]
    return t0.add(posQl.sub(q0).mul(t1.sub(t0)).div(q1.sub(q0))).toNumber()
  }
}

/**
 * Index `i` of the segment `[points[i], points[i+1]]` containing `x`.
 * Out-of-range `x` clamps to the first/last segment — the nearest-segment-
 * slope extrapolation rule (Python `_segment_index`, bisect_right - 1).
 * `pointsFloat` is an optional float mirror used to locate the search start
 * (exact Rational comparison then decides the boundary).
 */
function segmentIndex(
  points: readonly Rational[],
  pointsFloat: readonly number[] | null,
  x: Rational,
  xFloat: number,
): number {
  // bisect_right(points, x) on the float mirror, then exact verification.
  let i: number
  if (pointsFloat) {
    i = bisectRightFloat(pointsFloat, xFloat) - 1
  } else {
    i = bisectRightRational(points, x) - 1
  }
  if (i < 0) return 0
  return Math.min(i, points.length - 2)
}

function bisectRightFloat(xs: readonly number[], v: number): number {
  let lo = 0
  let hi = xs.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (v < xs[mid]) hi = mid
    else lo = mid + 1
  }
  return lo
}

function bisectRightRational(xs: readonly Rational[], v: Rational): number {
  let lo = 0
  let hi = xs.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (v.lt(xs[mid])) hi = mid
    else lo = mid + 1
  }
  return lo
}

import { describe, expect, it, vi } from 'vitest'
import { TransportCore } from './core'
import { FakeMediaPort } from './fakeMediaPort'
import type { TransportSnapshot } from './types'

function makeCore(duration = 60, opts?: ConstructorParameters<typeof TransportCore>[1]) {
  const port = new FakeMediaPort(duration)
  const core = new TransportCore(port, opts)
  port.seekTo(0)
  port.seeks.length = 0
  core.onLoaded(duration)
  return { core, port }
}

function collect(core: TransportCore) {
  const snaps: TransportSnapshot[] = []
  core.subscribe((s) => snaps.push(s))
  return snaps
}

describe('TransportCore lifecycle', () => {
  it('starts empty and becomes ready on load', () => {
    const port = new FakeMediaPort()
    const core = new TransportCore(port)
    expect(core.getSnapshot().status).toBe('empty')
    core.onLoadStart()
    expect(core.getSnapshot().status).toBe('loading')
    core.onLoaded(30)
    expect(core.getSnapshot().status).toBe('ready')
    expect(core.getDuration()).toBe(30)
  })

  it('rejects play/seek while empty or loading', async () => {
    const port = new FakeMediaPort()
    const core = new TransportCore(port)
    await core.play()
    await core.seek(5)
    expect(port.playCalls).toBe(0)
    expect(port.seeks).toEqual([])
    core.onLoadStart()
    await core.play()
    await core.seek(5)
    expect(port.playCalls).toBe(0)
    expect(port.seeks).toEqual([])
  })

  it('play → pause → ended transitions', async () => {
    const { core, port } = makeCore()
    await core.play()
    expect(core.getSnapshot().status).toBe('playing')
    core.pause()
    expect(core.getSnapshot().status).toBe('paused')
    port.time = port.duration
    core.onEnded()
    expect(core.getSnapshot().status).toBe('ended')
    // play() after end restarts from 0
    port.seeks.length = 0
    await core.play()
    expect(port.seeks).toEqual([0])
    expect(core.getSnapshot().status).toBe('playing')
  })
})

describe('TransportCore seek edges', () => {
  it('clamps seeks to [0, duration]', async () => {
    const { core, port } = makeCore(60)
    await core.seek(-5)
    expect(port.seeks.at(-1)).toBe(0)
    await core.seek(999)
    expect(port.seeks.at(-1)).toBe(60)
    await core.seek(12.5)
    expect(port.seeks.at(-1)).toBe(12.5)
    expect(core.getSnapshot().time).toBe(12.5)
  })

  it('treats NaN/Infinity seeks as 0', async () => {
    const { core, port } = makeCore()
    await core.seek(Number.NaN)
    expect(port.seeks.at(-1)).toBe(0)
    await core.seek(Number.POSITIVE_INFINITY)
    expect(port.seeks.at(-1)).toBe(0)
  })

  it('stop() returns to 0 without a loop and to loop.start with one', async () => {
    const { core, port } = makeCore()
    await core.seek(20)
    core.stop()
    expect(port.seeks.at(-1)).toBe(0)
    expect(core.getSnapshot().status).toBe('paused')

    core.setLoop({ start: 4, end: 8 })
    await core.seek(6)
    core.stop()
    expect(port.seeks.at(-1)).toBe(4)
  })
})

describe('TransportCore loop edges', () => {
  it('rejects degenerate or inverted ranges', () => {
    const { core } = makeCore(60)
    expect(core.setLoop({ start: 10, end: 10 })).toBe(false)
    expect(core.setLoop({ start: 10, end: 9 })).toBe(false)
    expect(core.setLoop({ start: -1, end: 0.001 })).toBe(false)
    expect(core.setLoop({ start: Number.NaN, end: 5 })).toBe(false)
    expect(core.getSnapshot().loop).toBeNull()
  })

  it('clamps ranges into [0, duration]', () => {
    const { core } = makeCore(60)
    expect(core.setLoop({ start: -3, end: 500 })).toBe(true)
    expect(core.getSnapshot().loop).toEqual({ start: 0, end: 60 })
  })

  it('wraps to loop.start when the clock crosses loop.end while playing', async () => {
    const wraps: number[] = []
    const { core, port } = makeCore(60, {
      onLoopWrap: (i) => wraps.push(i.overshoot),
    })
    core.setLoop({ start: 10, end: 12 })
    await core.seek(10.5)
    await core.play()
    port.seeks.length = 0

    port.time = 11.9
    core.onTick()
    expect(port.seeks).toEqual([]) // still inside

    port.time = 12.02 // overshoot the end between ticks
    core.onTick()
    expect(port.seeks.at(-1)).toBe(10)
    expect(wraps).toHaveLength(1)
    expect(wraps[0]).toBeCloseTo(0.02, 5)
    expect(core.getSnapshot().status).toBe('playing')
  })

  it('does not wrap when loop is cleared mid-flight', async () => {
    const { core, port } = makeCore()
    core.setLoop({ start: 10, end: 12 })
    await core.play()
    core.setLoop(null)
    port.seeks.length = 0
    port.time = 15
    core.onTick()
    expect(port.seeks).toEqual([])
    expect(core.getSnapshot().status).toBe('playing')
  })

  it('explicit seek outside the armed loop disarms until re-entry', async () => {
    const { core, port } = makeCore()
    core.setLoop({ start: 10, end: 12 })
    await core.play()

    // Escape: user seeks beyond the loop end while playing.
    await core.seek(20)
    port.seeks.length = 0
    port.time = 20.5
    core.onTick()
    expect(port.seeks).toEqual([]) // no snap-back

    // Playhead re-enters the range → enforcement re-arms.
    port.time = 11
    core.onTick()
    port.time = 12.01
    core.onTick()
    expect(port.seeks.at(-1)).toBe(10)
  })

  it('arming a loop while the playhead is inside enforces immediately', async () => {
    const { core, port } = makeCore()
    await core.play()
    port.time = 10.5
    core.onTick()
    expect(core.setLoop({ start: 10, end: 11 })).toBe(true)
    port.seeks.length = 0
    port.time = 11.05
    core.onTick()
    expect(port.seeks.at(-1)).toBe(10)
  })

  it('arming a loop while the playhead is beyond loop.end does not wrap', async () => {
    const { core, port } = makeCore()
    await core.play()
    port.time = 50
    core.onTick()
    port.seeks.length = 0
    core.setLoop({ start: 10, end: 11 })
    port.time = 55
    core.onTick()
    expect(port.seeks).toEqual([])
    expect(core.getSnapshot().status).toBe('playing')
  })

  it('reaching media end transitions to ended even with an armed loop outside', async () => {
    const { core, port } = makeCore(30)
    await core.play()
    core.setLoop({ start: 5, end: 8 }) // playhead at 0 → loop armed at start…
    port.time = 30
    core.onTick()
    expect(core.getSnapshot().status).toBe('ended')
  })
})

describe('TransportCore rate and pitch', () => {
  it('clamps rate to [MIN_RATE, MAX_RATE] and forwards to the port', () => {
    const { core, port } = makeCore()
    core.setRate(0.75)
    expect(port.rate).toBe(0.75)
    core.setRate(0.01)
    expect(port.rate).toBe(0.25)
    core.setRate(99)
    expect(port.rate).toBe(4)
    core.setRate(Number.NaN)
    expect(port.rate).toBe(4) // unchanged
  })

  it('forwards preservePitch changes', () => {
    const { core, port } = makeCore()
    expect(port.preservePitch).toBe(true)
    core.setPreservePitch(false)
    expect(port.preservePitch).toBe(false)
    expect(core.getSnapshot().preservePitch).toBe(false)
  })
})

describe('TransportCore subscription policy', () => {
  it('does not emit a snapshot for sub-interval time updates', async () => {
    const { core, port } = makeCore(60, { timeEmitInterval: 0.1 })
    await core.play()
    const snaps = collect(core)
    const before = snaps.length
    // 20 ticks × 4 ms = 80 ms < 100 ms threshold → no time-only emission
    for (let i = 0; i < 20; i += 1) {
      port.advance(0.004)
      core.onTick()
    }
    expect(snaps.length).toBe(before)
    port.advance(0.05)
    core.onTick() // cumulative advance past threshold
    expect(snaps.length).toBe(before + 1)
  })

  it('emits immediately on backward time moves (seeks)', async () => {
    const { core, port } = makeCore()
    await core.play()
    const snaps = collect(core)
    const before = snaps.length
    port.time = 1 // moved backward
    core.onTick()
    expect(snaps.length).toBe(before + 1)
  })

  it('unsubscribe stops notifications', async () => {
    const { core } = makeCore()
    const listener = vi.fn()
    const off = core.subscribe(listener)
    await core.play()
    expect(listener).toHaveBeenCalled()
    off()
    core.pause()
    expect(listener.mock.calls.length).toBe(1)
  })
})

import {
  MAX_RATE,
  MIN_LOOP_SECONDS,
  MIN_RATE,
  type LoopWrapInfo,
  type TimeRange,
  type TransportListener,
  type TransportSnapshot,
  type TransportStatus,
  type Unsubscribe,
} from './types'

/**
 * Minimal media engine surface the TransportCore drives.
 * Implemented by WaveSurferTransportAdapter (wavesurfer/HTMLMediaElement)
 * and by FakeMediaPort in tests. This is the adapter boundary the product
 * keeps: swap the engine without touching transport logic.
 */
export interface MediaPort {
  play(): Promise<void> | void
  pause(): void
  /** Absolute seek in seconds. Implementations must clamp to media bounds. */
  seekTo(seconds: number): void
  setRate(rate: number): void
  setPreservePitch(on: boolean): void
  /** Authoritative audio clock, seconds. May be NaN before load. */
  getTime(): number
  /** Media duration in seconds. 0/NaN while unknown. */
  getDuration(): number
}

export interface TransportCoreOptions {
  /**
   * Minimum audio-clock advance (seconds) before a time-only snapshot is
   * emitted from onTick(). Keeps listeners (e.g. React state) off the
   * per-frame path; the clock itself is always available via getTime().
   */
  timeEmitInterval?: number
  /** Called after every loop wrap with the observed boundary times. */
  onLoopWrap?: (info: LoopWrapInfo) => void
}

const DEFAULT_TIME_EMIT_INTERVAL = 0.1

/**
 * HornScribe-owned transport state machine. Headless and DOM-free:
 * the MediaPort supplies the clock and playback, this class owns policy —
 * clamping, status transitions, and A-B loop enforcement.
 *
 * Loop semantics (documented for the spike):
 *  - loop = half-open [start, end); while playing, reaching `end` wraps to `start`.
 *  - an explicit seek() landing outside the armed loop disarms enforcement
 *    until the playhead re-enters [start, end) — the user can escape the loop
 *    without clearing it.
 *  - setLoop(null) clears immediately; the next wrap never happens.
 */
export class TransportCore {
  private port: MediaPort
  private listeners = new Set<TransportListener>()
  private opts: Required<Pick<TransportCoreOptions, 'timeEmitInterval'>> & TransportCoreOptions

  private status: TransportStatus = 'empty'
  private duration = 0
  private time = 0
  private lastEmittedTime = 0
  private rate = 1
  private preservePitch = true
  private loop: TimeRange | null = null
  /** Whether loop-end enforcement currently applies. See class doc. */
  private loopArmed = false
  private revision = 0

  constructor(port: MediaPort, opts: TransportCoreOptions = {}) {
    this.port = port
    this.opts = { timeEmitInterval: opts.timeEmitInterval ?? DEFAULT_TIME_EMIT_INTERVAL, ...opts }
  }

  // ---- queries -----------------------------------------------------------

  getSnapshot(): TransportSnapshot {
    return {
      status: this.status,
      time: this.time,
      duration: this.duration,
      rate: this.rate,
      preservePitch: this.preservePitch,
      loop: this.loop ? { ...this.loop } : null,
      revision: this.revision,
    }
  }

  getTime(): number {
    const t = this.port.getTime()
    return Number.isFinite(t) ? t : this.time
  }

  getDuration(): number {
    return this.duration
  }

  isPlaying(): boolean {
    return this.status === 'playing'
  }

  isLoopArmed(): boolean {
    return this.loopArmed
  }

  // ---- lifecycle (called by the adapter's engine events) -----------------

  onLoadStart(): void {
    this.status = 'loading'
    this.duration = 0
    this.time = 0
    this.lastEmittedTime = 0
    this.loop = null
    this.loopArmed = false
    this.emit()
  }

  onLoaded(duration: number): void {
    this.duration = Number.isFinite(duration) ? Math.max(0, duration) : 0
    this.status = 'ready'
    this.time = 0
    this.emit()
  }

  onPlayStart(): void {
    if (this.status !== 'playing') {
      this.status = 'playing'
      this.emit()
    }
  }

  onPaused(): void {
    if (this.status === 'playing') {
      this.status = 'paused'
      this.time = this.getTime()
      this.emit()
    }
  }

  onEnded(): void {
    this.status = 'ended'
    this.time = this.getTime()
    this.emit()
  }

  onError(): void {
    this.status = 'error'
    this.emit()
  }

  // ---- commands ----------------------------------------------------------

  async play(): Promise<void> {
    if (this.status === 'empty' || this.status === 'loading' || this.status === 'error') return
    if (this.status === 'ended') {
      this.seekInternal(0)
    }
    this.status = 'playing'
    this.emit()
    await this.port.play()
  }

  pause(): void {
    if (this.status !== 'playing') return
    this.port.pause()
    this.status = 'paused'
    this.time = this.getTime()
    this.emit()
  }

  stop(): void {
    if (this.status === 'empty' || this.status === 'loading') return
    if (this.status === 'playing') this.port.pause()
    this.status = 'paused'
    this.seekInternal(this.loop ? this.loop.start : 0)
    this.emit()
  }

  async seek(seconds: number): Promise<void> {
    if (this.status === 'empty' || this.status === 'loading') return
    const t = this.clampTime(seconds)
    // An explicit user seek outside the armed loop disarms enforcement until
    // the playhead re-enters the range (see class doc).
    if (this.loopArmed && this.loop && !this.inLoop(t)) {
      this.loopArmed = false
    }
    if (this.loop && !this.loopArmed && this.inLoop(t)) {
      this.loopArmed = true
    }
    this.seekInternal(t)
    this.emit()
    if (this.status === 'ended') {
      this.status = 'paused'
      this.emit()
    }
  }

  setRate(rate: number): void {
    if (!Number.isFinite(rate)) return
    const clamped = Math.min(MAX_RATE, Math.max(MIN_RATE, rate))
    if (clamped === this.rate) return
    this.rate = clamped
    this.port.setRate(clamped)
    this.emit()
  }

  setPreservePitch(on: boolean): void {
    if (on === this.preservePitch) return
    this.preservePitch = on
    this.port.setPreservePitch(on)
    this.emit()
  }

  /**
   * Arm or clear the A-B loop. Returns false when the range is unusable
   * (inverted, shorter than MIN_LOOP_SECONDS, or outside the media).
   */
  setLoop(range: TimeRange | null): boolean {
    if (range === null) {
      if (this.loop === null) return false
      this.loop = null
      this.loopArmed = false
      this.emit()
      return true
    }
    const normalized = this.normalizeRange(range)
    if (normalized === null) return false
    this.loop = normalized
    this.loopArmed = this.inLoop(this.getTime())
    this.emit()
    return true
  }

  // ---- clock path --------------------------------------------------------

  /**
   * Called by the adapter's clock pump (rAF while playing, plus on seek/
   * media events). Reads the audio clock and enforces the loop boundary.
   */
  onTick(): void {
    const t = this.getTime()
    const prev = this.time
    this.time = t

    if (this.status === 'playing' && this.loop && this.loopArmed && t >= this.loop.end) {
      const info: LoopWrapInfo = { expected: this.loop.end, actual: t, overshoot: t - this.loop.end }
      const start = this.loop.start
      this.port.seekTo(start)
      this.time = start
      this.opts.onLoopWrap?.(info)
      this.emit()
      return
    }

    // Re-arm once the playhead is inside the loop range again.
    if (this.loop && !this.loopArmed && this.inLoop(t)) {
      this.loopArmed = true
    }

    if (this.status === 'playing' && this.duration > 0 && t >= this.duration) {
      this.status = 'ended'
      this.emit()
      return
    }

    // Throttle time-only emissions; mutations elsewhere emit immediately.
    if (Math.abs(t - this.lastEmittedTime) >= this.opts.timeEmitInterval || t < prev) {
      this.emit()
    }
  }

  // ---- subscriptions -----------------------------------------------------

  subscribe(listener: TransportListener): Unsubscribe {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  private emit(): void {
    this.revision += 1
    this.lastEmittedTime = this.time
    const snapshot = this.getSnapshot()
    for (const l of this.listeners) l(snapshot)
  }

  // ---- internals ---------------------------------------------------------

  private seekInternal(t: number): void {
    this.port.seekTo(t)
    this.time = t
  }

  private clampTime(t: number): number {
    if (!Number.isFinite(t)) return 0
    const upper = this.duration > 0 ? this.duration : Number.POSITIVE_INFINITY
    return Math.min(upper, Math.max(0, t))
  }

  private inLoop(t: number): boolean {
    return this.loop !== null && t >= this.loop.start && t < this.loop.end
  }

  private normalizeRange(range: TimeRange): TimeRange | null {
    const { start, end } = range
    if (!Number.isFinite(start) || !Number.isFinite(end)) return null
    const s = Math.max(0, start)
    const e = this.duration > 0 ? Math.min(this.duration, end) : end
    if (e - s < MIN_LOOP_SECONDS) return null
    return { start: s, end: e }
  }
}

import type { MediaPort } from './core'

/**
 * Deterministic MediaPort for headless tests: the "audio clock" is a manual
 * cursor that the test advances with advance(). No DOM, no timers.
 */
export class FakeMediaPort implements MediaPort {
  time = 0
  duration = 0
  rate = 1
  preservePitch = true
  playing = false
  playCalls = 0
  pauseCalls = 0
  /** Every seek target, in order. */
  seeks: number[] = []

  constructor(duration = 60) {
    this.duration = duration
  }

  play(): Promise<void> {
    this.playCalls += 1
    this.playing = true
    return Promise.resolve()
  }

  pause(): void {
    this.pauseCalls += 1
    this.playing = false
  }

  seekTo(seconds: number): void {
    this.seeks.push(seconds)
    this.time = seconds
  }

  setRate(rate: number): void {
    this.rate = rate
  }

  setPreservePitch(on: boolean): void {
    this.preservePitch = on
  }

  getTime(): number {
    return this.time
  }

  getDuration(): number {
    return this.duration
  }

  /** Advance the fake audio clock as if playback ran `dt` seconds. */
  advance(dt: number): void {
    this.time += dt * this.rate
  }
}

/**
 * TransportController contract for HornScribe (UI-004 spike).
 *
 * Mirrors docs/MASTER_PLAN.md §10 (`interface TransportController`) with the
 * spike additions needed to exercise the surface (load/stop/preservePitch/
 * dispose). HornScribe owns this interface: wavesurfer.js and
 * HTMLMediaElement are adapters/views, never the business-logic source of
 * truth. The authoritative clock is the audio clock exposed through
 * getCurrentTime(), not React state and not the waveform view.
 */

/** Half-open time range in seconds: [start, end). */
export interface TimeRange {
  start: number
  end: number
}

export type TransportStatus =
  | 'empty' // nothing loaded
  | 'loading' // load requested, not yet ready
  | 'ready' // loaded, cursor parked
  | 'playing'
  | 'paused'
  | 'ended' // reached end of media while playing
  | 'error'

export interface TransportSnapshot {
  status: TransportStatus
  /** Audio-clock time in seconds. Low-frequency mirror — see getCurrentTime(). */
  time: number
  /** Duration in seconds (0 while empty/loading). */
  duration: number
  /** Playback rate multiplier. */
  rate: number
  /** Whether pitch preservation is requested for rate != 1. */
  preservePitch: boolean
  /** Active A-B loop range, or null when looping is off. */
  loop: TimeRange | null
  /** Monotonic counter bumped on every emitted snapshot. */
  revision: number
}

export type TransportListener = (snapshot: TransportSnapshot) => void
export type Unsubscribe = () => void

/** Source the transport can load. */
export type AudioSource = { kind: 'url'; url: string } | { kind: 'blob'; blob: Blob }

export interface LoopWrapInfo {
  /** Loop end the playhead was supposed to wrap at (seconds). */
  expected: number
  /** Audio-clock time observed when the wrap check fired (seconds). */
  actual: number
  /** actual - expected: overshoot past the loop end before wrapping. */
  overshoot: number
}

export interface TransportController {
  /** Load a source. Resolves when decoded + ready to play. */
  load(source: AudioSource): Promise<void>
  play(): Promise<void>
  pause(): void
  /** Pause and return to t=0 (or the loop start when a loop is armed). */
  stop(): void
  /** Seek to an absolute position in seconds. Clamped to [0, duration]. */
  seek(seconds: number): Promise<void>
  /** Set playback rate. Spike accepts [MIN_RATE..MAX_RATE], clamped. */
  setRate(rate: number): void
  /** Request pitch preservation for rate != 1 (where the backend supports it). */
  setPreservePitch(on: boolean): void
  /** Arm (TimeRange) or clear (null) the A-B loop. */
  setLoop(range: TimeRange | null): void
  /** Authoritative audio-clock time in seconds. Read on demand (rAF ok). */
  getCurrentTime(): number
  getDuration(): number
  getSnapshot(): TransportSnapshot
  subscribe(listener: TransportListener): Unsubscribe
  dispose(): void
}

export const MIN_RATE = 0.25
export const MAX_RATE = 4
export const SUPPORTED_RATES = [0.5, 0.75, 1, 1.25, 1.5] as const
/** Loops shorter than this are rejected (noise-level accidental drags). */
export const MIN_LOOP_SECONDS = 0.01

import WaveSurfer from 'wavesurfer.js'
import RegionsPlugin, { type Region } from 'wavesurfer.js/dist/plugins/regions.js'
import { TransportCore, type MediaPort, type TransportCoreOptions } from './core'
import type {
  AudioSource,
  LoopWrapInfo,
  TimeRange,
  TransportController,
  TransportListener,
  TransportSnapshot,
  Unsubscribe,
} from './types'

export interface WaveSurferAdapterOptions extends TransportCoreOptions {
  container: HTMLElement
  height?: number
  waveColor?: string
  progressColor?: string
  cursorColor?: string
  /** Region fill while it is a plain selection (loop off). */
  selectionColor?: string
  /** Region fill while the selection is armed as the A-B loop. */
  loopColor?: string
  /** Called when a loop wrap occurs (measurement hook). */
  onLoopWrap?: (info: LoopWrapInfo) => void
}

/**
 * wavesurfer.js adapter for the HornScribe TransportController.
 *
 * Boundary rules (MASTER_PLAN §4.7/§10):
 *  - TransportCore owns state + policy; this class only translates between
 *    wavesurfer/HTMLMediaElement and the core.
 *  - The clock is the media element clock, pumped through a rAF loop owned
 *    here — never React state and never wavesurfer view state.
 *  - The loop region is a *view* of TransportCore.loop + the current drag
 *    selection; engine details (Regions plugin) do not leak past this file.
 */
export class WaveSurferTransportAdapter implements TransportController {
  readonly core: TransportCore
  private ws: WaveSurfer
  private regions: RegionsPlugin
  private unsubscribers: Unsubscribe[] = []
  private rafId: number | null = null
  private selectionRegion: Region | null = null
  /** Current waveform selection (region view state, not core state). */
  private selection: TimeRange | null = null
  private syncingRegion = false
  private loadTiming: { fetchDecodeMs: number; readyMs: number } | null = null
  private wrapListeners = new Set<(info: LoopWrapInfo) => void>()
  private selectionListener: ((sel: TimeRange | null) => void) | null = null

  constructor(opts: WaveSurferAdapterOptions) {
    const ws = WaveSurfer.create({
      container: opts.container,
      height: opts.height ?? 112,
      waveColor: opts.waveColor ?? '#4a6f9e',
      progressColor: opts.progressColor ?? '#7fb3ff',
      cursorColor: opts.cursorColor ?? '#e8b339',
      cursorWidth: 2,
      autoScroll: true,
      autoCenter: false,
      // dragToSeek MUST stay off: its document-level pointermove handler calls
      // preventDefault(), which starves the Regions plugin's drag-selection
      // stream (it bails on event.defaultPrevented). Drag = range select;
      // click = seek via the normal interaction path.
      dragToSeek: false,
      minPxPerSec: 0,
      fillParent: true,
      hideScrollbar: false,
    })
    this.ws = ws

    this.regions = ws.registerPlugin(RegionsPlugin.create())
    this.regions.enableDragSelection({
      color: opts.selectionColor ?? 'rgba(232, 179, 57, 0.25)',
      drag: true,
      resize: true,
    })

    const port: MediaPort = {
      play: () => ws.play(),
      pause: () => ws.pause(),
      seekTo: (t) => ws.setTime(t),
      setRate: (rate) => ws.setPlaybackRate(rate, this.core.getSnapshot().preservePitch),
      setPreservePitch: (on) => this.applyPreservePitch(on),
      getTime: () => {
        const media = ws.getMediaElement()
        return media ? media.currentTime : ws.getCurrentTime()
      },
      getDuration: () => ws.getDuration(),
    }
    this.core = new TransportCore(port, {
      ...opts,
      onLoopWrap: (info) => {
        for (const cb of this.wrapListeners) cb(info)
        opts.onLoopWrap?.(info)
      },
    })

    this.wireEvents()
  }

  // ---- TransportController ------------------------------------------------

  async load(source: AudioSource): Promise<void> {
    const t0 = performance.now()
    let decodeAt = 0
    const offs: Unsubscribe[] = []
    const ready = new Promise<void>((resolve, reject) => {
      const cleanup = () => offs.splice(0).forEach((off) => off())
      offs.push(
        this.ws.once('ready', () => {
          this.loadTiming = { fetchDecodeMs: decodeAt - t0, readyMs: performance.now() - t0 }
          cleanup()
          resolve()
        }),
        this.ws.once('error', (err) => {
          cleanup()
          reject(err instanceof Error ? err : new Error(String(err)))
        }),
        this.ws.on('decode', () => {
          decodeAt = performance.now()
        }),
      )
    })
    this.core.onLoadStart()
    if (source.kind === 'blob') {
      void this.ws.loadBlob(source.blob)
    } else {
      void this.ws.load(source.url)
    }
    await ready
  }

  /** Wall-clock ms for fetch+decode ('load'→'decode') and total to 'ready'. */
  getLoadTiming(): { fetchDecodeMs: number; readyMs: number } | null {
    return this.loadTiming
  }

  play(): Promise<void> {
    return this.core.play()
  }

  pause(): void {
    this.core.pause()
  }

  stop(): void {
    this.core.stop()
  }

  async seek(seconds: number): Promise<void> {
    // Attach the 'seeked' waiter BEFORE issuing the seek — a fast seek can
    // complete before a post-hoc listener is attached.
    const media = this.ws.getMediaElement()
    let finish: () => void = () => {}
    const settled = new Promise<void>((resolve) => {
      if (!media) return resolve()
      let done = false
      finish = () => {
        if (done) return
        done = true
        media.removeEventListener('seeked', finish)
        resolve()
      }
      media.addEventListener('seeked', finish)
      setTimeout(finish, 800)
    })
    await this.core.seek(seconds)
    // If the UA applied the seek synchronously there is nothing to wait for.
    if (!media || !media.seeking) finish()
    await settled
  }

  setRate(rate: number): void {
    this.core.setRate(rate)
  }

  setPreservePitch(on: boolean): void {
    this.core.setPreservePitch(on)
  }

  private applyPreservePitch(on: boolean): void {
    const media = this.ws.getMediaElement()
    if (media && 'preservesPitch' in media) {
      media.preservesPitch = on
    }
    // wavesurfer re-asserts preservesPitch on every setPlaybackRate call;
    // re-apply with the current rate so the flag takes effect now.
    this.ws.setPlaybackRate(this.core.getSnapshot().rate, on)
  }

  setLoop(range: TimeRange | null): void {
    const applied = this.core.setLoop(range)
    if (!applied) return
    if (range !== null) {
      // Contract callers may arm a loop with no prior selection: materialize
      // the region view so the loop is visible and adjustable.
      const s = this.core.getSnapshot().loop
      if (s) {
        this.selection = { ...s }
        this.syncingRegion = true
        if (!this.selectionRegion || this.selectionRegion.isRemoved) {
          this.selectionRegion = this.regions.addRegion({
            start: s.start,
            end: s.end,
            drag: true,
            resize: true,
            color: 'rgba(96, 203, 148, 0.30)',
          })
        } else {
          this.selectionRegion.setOptions({ start: s.start, end: s.end })
        }
        this.syncingRegion = false
      }
    }
    this.refreshRegionStyle()
  }

  getCurrentTime(): number {
    return this.core.getTime()
  }

  getDuration(): number {
    return this.core.getDuration()
  }

  getSnapshot(): TransportSnapshot {
    return this.core.getSnapshot()
  }

  subscribe(listener: TransportListener): Unsubscribe {
    return this.core.subscribe(listener)
  }

  dispose(): void {
    this.stopClock()
    for (const off of this.unsubscribers) off()
    this.ws.destroy()
  }

  // ---- adapter extras (view/measurement surface, not contract) ------------

  /** Escape hatch for the spike view layer (plugins, scroll, peaks). */
  getWavesurfer(): WaveSurfer {
    return this.ws
  }

  /** Regions plugin handle (measurement/tests; region objects are view state). */
  getRegionsPlugin(): RegionsPlugin {
    return this.regions
  }

  /** Observe loop wraps (measurement). Returns an unsubscribe function. */
  onLoopWrap(cb: (info: LoopWrapInfo) => void): Unsubscribe {
    this.wrapListeners.add(cb)
    return () => this.wrapListeners.delete(cb)
  }

  /** Selection (region) changes — view-level state, distinct from the loop. */
  setSelectionListener(cb: ((sel: TimeRange | null) => void) | null): void {
    this.selectionListener = cb
  }

  private emitSelection(): void {
    this.selectionListener?.(this.selection ? { ...this.selection } : null)
  }

  getSelection(): TimeRange | null {
    return this.selection ? { ...this.selection } : null
  }

  clearSelection(): void {
    this.selection = null
    this.syncingRegion = true
    this.selectionRegion?.remove()
    this.selectionRegion = null
    this.syncingRegion = false
    this.setLoop(null)
    this.emitSelection()
  }

  /** Play the current selection once (stops at its end). */
  async playSelection(): Promise<void> {
    if (!this.selection) return
    await this.core.seek(this.selection.start)
    await this.core.play()
    // One-shot playback-to-end: park the "stop" via a tick watcher.
    const end = this.selection.end
    const off = this.core.subscribe(() => {
      if (this.core.getTime() >= end && this.core.isPlaying()) {
        off()
        this.core.pause()
      }
    })
  }

  /** Zoom in pixels-per-second; clamped to fit-parent..4000. */
  zoom(pxPerSec: number): void {
    const duration = this.ws.getDuration()
    const width = this.ws.getWidth() || 1
    const fitPx = duration > 0 ? width / duration : 1
    const clamped = Math.max(fitPx, Math.min(4000, pxPerSec))
    this.ws.zoom(clamped)
  }

  getZoomPxPerSec(): number {
    const duration = this.ws.getDuration()
    if (this.ws.options.minPxPerSec && this.ws.options.minPxPerSec > 0) {
      return this.ws.options.minPxPerSec
    }
    const width = this.ws.getWidth() || 1
    return duration > 0 ? width / duration : 1
  }

  /** Ctrl+wheel zoom anchored at the cursor position (copy deck: Ctrl+ホイール). */
  attachWheelZoom(): Unsubscribe {
    const wrapper = this.ws.getWrapper()
    const onWheel = (e: WheelEvent) => {
      if (!e.ctrlKey || Math.abs(e.deltaX) >= Math.abs(e.deltaY)) return
      e.preventDefault()
      const duration = this.ws.getDuration()
      if (!duration) return
      const rect = wrapper.getBoundingClientRect()
      const x = e.clientX - rect.left
      const px = this.getZoomPxPerSec()
      const pointerTime = (this.ws.getScroll() + x) / px
      const factor = e.deltaY < 0 ? 1.2 : 1 / 1.2
      const next = Math.min(4000, Math.max(rect.width / duration, px * factor))
      this.ws.zoom(next)
      wrapper.scrollLeft = Math.max(0, pointerTime * next - x)
    }
    wrapper.addEventListener('wheel', onWheel, { passive: false })
    return () => wrapper.removeEventListener('wheel', onWheel)
  }

  setFollow(on: boolean): void {
    this.ws.setOptions({ autoScroll: on, autoCenter: on })
  }

  // ---- engine wiring -------------------------------------------------------

  private wireEvents(): void {
    const ws = this.ws
    this.unsubscribers.push(
      ws.on('ready', (d) => {
        this.core.onLoaded(d)
        this.applyPreservePitch(this.core.getSnapshot().preservePitch)
      }),
      ws.on('play', () => {
        this.core.onPlayStart()
        this.startClock()
      }),
      ws.on('pause', () => {
        this.core.onPaused()
        this.stopClock()
      }),
      ws.on('finish', () => {
        this.core.onEnded()
        this.stopClock()
      }),
      ws.on('error', () => {
        this.core.onError()
        this.stopClock()
      }),
      ws.on('seeking', () => this.core.onTick()),
      ws.on('timeupdate', () => {
        // Covers seeks while paused and any timeupdate outside the rAF pump.
        if (!this.core.isPlaying()) this.core.onTick()
      }),
    )

    this.unsubscribers.push(
      this.regions.on('region-created', (region) => {
        if (this.syncingRegion) return
        // Drag-select replaces the previous selection region.
        if (this.selectionRegion && this.selectionRegion !== region) {
          this.syncingRegion = true
          this.selectionRegion.remove()
          this.syncingRegion = false
        }
        this.selectionRegion = region
        // 'region-updated' does NOT fire for the initial drag — capture the
        // range here; handle drags come through 'region-updated' below.
        this.selection = { start: region.start, end: region.end }
        this.emitSelection()
        this.refreshRegionStyle()
      }),
      this.regions.on('region-updated', (region) => {
        if (this.syncingRegion || region !== this.selectionRegion) return
        this.selection = { start: region.start, end: region.end }
        this.emitSelection()
        // While a loop is armed, moving the selection moves the loop.
        if (this.core.getSnapshot().loop) {
          this.core.setLoop(this.selection)
        }
      }),
      this.regions.on('region-removed', (region) => {
        if (region === this.selectionRegion) {
          this.selectionRegion = null
          this.selection = null
          this.emitSelection()
          if (this.core.getSnapshot().loop) this.core.setLoop(null)
        }
      }),
      this.regions.on('region-double-clicked', (region, e) => {
        e.stopPropagation()
        if (region === this.selectionRegion) this.clearSelection()
      }),
    )
  }

  /** rAF clock pump: the transport owns loop enforcement + time emission. */
  private startClock(): void {
    if (this.rafId !== null) return
    const tick = () => {
      this.core.onTick()
      if (this.core.isPlaying()) {
        this.rafId = requestAnimationFrame(tick)
      } else {
        this.rafId = null
      }
    }
    this.rafId = requestAnimationFrame(tick)
  }

  private stopClock(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
  }

  private refreshRegionStyle(): void {
    const looped = this.core.getSnapshot().loop !== null
    this.selectionRegion?.setOptions({
      color: looped ? 'rgba(96, 203, 148, 0.30)' : 'rgba(232, 179, 57, 0.25)',
    })
  }
}

/**
 * Minimal typings for the `verovio` npm package (v6.x ships no .d.ts).
 * Covers only the toolkit surface exercised by the UI-003 spike.
 * API reference: https://book.verovio.org/toolkit-reference/toolkit-methods.html
 */
declare module 'verovio/wasm' {
  /** Emscripten module hosting the Verovio WASM binary (inlined in the dist file). */
  export interface VerovioModule {
    readonly [key: string]: unknown;
  }
  export default function createVerovioModule(
    moduleArg?: Record<string, unknown>,
  ): Promise<VerovioModule>;
}

declare module 'verovio/esm' {
  import type { VerovioModule } from 'verovio/wasm';

  export interface VerovioElementsAtTime {
    notes: string[];
    chords: string[];
    rests: string[];
    measure?: string;
    page?: number;
  }

  export interface VerovioTimesForElement {
    tstampOn: number[];
    tstampOff: number[];
    qfracOn?: number[][];
    qfracOff?: number[][];
    qfracDuration?: number[][];
    qfracTiedDuration?: number[][];
  }

  export interface VerovioTimemapEntry {
    on?: string[];
    off?: string[];
    qstamp: number;
    tstamp: number;
    tempo?: number;
  }

  export class VerovioToolkit {
    constructor(module?: VerovioModule);
    setOptions(options: Record<string, unknown>): boolean;
    getOptions(defaultValues?: boolean): Record<string, unknown>;
    loadData(data: string): boolean;
    renderToSVG(page: number): string;
    getPageCount(): number;
    /** The ESM wrapper JSON.parses internally — returns the parsed array. */
    renderToTimemap(options?: Record<string, unknown>): VerovioTimemapEntry[];
    getElementsAtTime(milliseconds: number): VerovioElementsAtTime;
    getTimeForElement(xmlId: string): number;
    getTimesForElement(xmlId: string): VerovioTimesForElement;
    getPageWithElement(xmlId: string): number;
    getElementAttr(xmlId: string): Record<string, unknown>;
    getVersion(): string;
    destroy?(): void;
  }
}

